(window.KOTOBA_HK=window.KOTOBA_HK||{})[22]={"n":22,"S":[{"id":"l22a","ti":[[["たぬき","たぬき"],["の","の"],["糸車","いとぐるま"]]],"tt":{"az":"Tanuki və ip əyirən çarx","en":"The Tanuki and the Spinning Wheel","ru":"Тануки и прялка"},"P":[{"t":[[["むかしむかし","むかしむかし"],["、"],["山","やま"],["の","の"],["近く","ちかく"],["に","に"],["、"],["小さな","ちいさな"],["家","いえ"],["が","が"],["ありました","ありました","ある",2],["。"],["その","その"],["家","いえ"],["に","に"],["は","は"],["、"],["おじいさん","おじいさん"],["と","と"],["おばあさん","おばあさん"],["が","が"],["住んでいました","すんでいました","住む",31],["。"],["おばあさん","おばあさん"],["は","は"],["、"],["毎晩","まいばん"],["、"],["糸車","いとぐるま"],["で","で"],["糸","いと"],["を","を"],["作りました","つくりました","作る",2],["。"],["おばあさん","おばあさん"],["が","が"],["作る","つくる","作る",5],["糸","いと"],["は","は"],["、"],["とても","とても"],["きれい","きれい"],["でした","でした","です",9],["。"]]],"tr":{"az":"Biri var idi, biri yox idi, dağın yaxınlığında balaca bir ev var idi. Bu evdə bir qoca kişi ilə qoca qadın yaşayırdı. Qoca qadın hər axşam çarxla ip əyirirdi. Onun əyirdiyi iplər çox gözəl olurdu.","en":"Long, long ago, there was a small house near a mountain. An old man and an old woman lived there. Every evening, the old woman made thread with a spinning wheel. The thread she made was very beautiful.","ru":"Давным-давно возле горы стоял маленький дом. В нём жили старик и старушка. Каждый вечер старушка пряла нить на прялке. Нити, которые она пряла, были очень красивыми."}},{"t":[[["ある","ある","ある(連体詞)"],["寒い","さむい"],["夜","よる"],["、"],["おばあさん","おばあさん"],["は","は"],["窓","まど"],["の","の"],["外","そと"],["で","で"],["小さな","ちいさな"],["音","おと"],["を","を"],["聞きました","ききました","聞く",2],["。"],["窓","まど"],["の","の"],["下","した"],["に","に"],["は","は"],["、"],["茶色い","ちゃいろい"],["たぬき","たぬき"],["が","が"],["いました","いました","いる",2],["。"],["たぬき","たぬき"],["は","は"],["、"],["おばあさん","おばあさん"],["が","が"],["使っている","つかっている","使う",26],["糸車","いとぐるま"],["を","を"],["じっと","じっと"],["見ていました","みていました","見る",15],["。"],["そして","そして"],["、"],["糸車","いとぐるま"],["の","の"],["音","おと"],["に","に"],["合わせて","あわせて","合わせて",3],["、"],["前","まえ"],["の","の"],["足","あし"],["を","を"],["くるくる","くるくる"],["動かしました","うごかしました","動かす",2],["。"]]],"tr":{"az":"Soyuq bir gecə qoca qadın pəncərənin çölündən zəif bir səs eşitdi. Pəncərənin altında qəhvəyi bir tanuki var idi. Tanuki qadının istifadə etdiyi ip çarxına diqqətlə baxırdı. Sonra çarxın səsinə uyğun olaraq qabaq pəncələrini dairəvi hərəkət etdirməyə başladı.","en":"One cold night, the old woman heard a little sound outside the window. A brown tanuki was sitting beneath it. The tanuki was staring at the spinning wheel the old woman was using. Then it began moving its front paws in circles to the sound of the wheel.","ru":"Однажды холодной ночью старушка услышала тихий звук за окном. Под окном сидел коричневый тануки. Он внимательно смотрел на прялку, которой пользовалась старушка. Затем он начал вращать передними лапками в такт звуку прялки."}},{"t":[[["「"],["まあ","まあ"],["、"],["かわいい","かわいい"],["たぬき","たぬき"],["です","です"],["ね","ね"],["」"],["と","と"],["、"],["おばあさん","おばあさん"],["は","は"],["笑いました","わらいました","笑う",2],["。"],["でも","でも"],["、"],["おじいさん","おじいさん"],["は","は"],["少し","すこし"],["心配","しんぱい"],["しました","しました","する",2],["。"],["「"],["たぬき","たぬき"],["が","が"],["家","いえ"],["に","に"],["入る","はいる","入る",5],["と","と"],["、"],["食べ物","たべもの"],["が","が"],["なくなる","なくなる","なくなる",5],["か","か"],["も","も"],["しれない","しれない","しれない",19],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["おばあさん","おばあさん"],["は","は"],["、"],["「"],["この","この"],["子","こ"],["は","は"],["悪い","わるい"],["たぬき","たぬき"],["で","で"],["は","は"],["ありません","ありません","ある",6],["よ","よ"],["」"],["と","と"],["言いました","いいました","言う",2],["。"]]],"tr":{"az":"«Ay, necə də şirin tanukidir!» deyə qoca qadın gülümsədi. Amma qoca kişi bir az narahat oldu. «Tanuki evə girsə, yeməklərimiz yoxa çıxa bilər», dedi. Qadın isə «Bu balaca pis tanuki deyil», deyə cavab verdi.","en":"“Oh, what a cute tanuki!” the old woman said with a smile. But the old man was a little worried. “If the tanuki comes inside, our food might disappear,” he said. “This little one isn't a bad tanuki,” the old woman replied.","ru":"«Ах, какой милый тануки!» – улыбнулась старушка. Но старик немного забеспокоился. «Если тануки войдёт в дом, наша еда может исчезнуть», – сказал он. «Этот малыш совсем не плохой тануки», – ответила старушка."}},{"t":[[["次","つぎ"],["の","の"],["朝","あさ"],["、"],["おばあさん","おばあさん"],["は","は"],["町","まち"],["へ","へ"],["行く","いく","行く",5],["用事","ようじ"],["が","が"],["ありました","ありました","ある",2],["。"],["おじいさん","おじいさん"],["も","も"],["山","やま"],["へ","へ"],["行きました","いきました","行く",2],["。"],["二人","ふたり"],["が","が"],["帰る","かえる","帰る",5],["時間","じかん"],["は","は"],["、"],["夕方","ゆうがた"],["でした","でした","です",9],["。"],["おばあさん","おばあさん"],["は","は"],["窓","まど"],["を","を"],["閉めて","しめて","閉める",3],["、"],["家","いえ"],["を","を"],["出ました","でました","出る",2],["。"],["でも","でも"],["、"],["小さな","ちいさな"],["窓","まど"],["が","が"],["一つ","ひとつ"],["開いていました","ひらいていました","開く",15],["。"]]],"tr":{"az":"Ertəsi səhər qoca qadının şəhərdə işi var idi. Qoca kişi də dağa getdi. İkisinin evə qayıdacağı vaxt axşamüstü idi. Qadın pəncərələri bağlayıb evdən çıxdı. Amma balaca pəncərələrdən biri açıq qalmışdı.","en":"The next morning, the old woman had something to do in town. The old man went to the mountain too. They were due to return in the evening. The old woman closed the windows and left the house. But one small window remained open.","ru":"На следующее утро старушке нужно было сходить по делам в город. Старик тоже отправился в горы. Оба должны были вернуться вечером. Старушка закрыла окна и вышла из дома. Но одно маленькое окно осталось открытым."}},{"t":[[["夕方","ゆうがた"],["、"],["おばあさん","おばあさん"],["が","が"],["帰る","かえる","帰る",5],["と","と"],["、"],["家","いえ"],["の","の"],["中","なか"],["から","から"],["糸車","いとぐるま"],["の","の"],["音","おと"],["が","が"],["聞こえました","きこえました","聞こえる",2],["。"],["「"],["ええ","ええ"],["と","と"],["、"],["おじいさん","おじいさん"],["は","は"],["もう","もう"],["帰った","かえった","帰る",0],["の","の"],["かしら","かしら"],["」"],["と","と"],["思いました","おもいました","思う",2],["。"],["そっと","そっと"],["戸","と"],["を","を"],["開ける","あける","開ける",5],["と","と"],["、"],["たぬき","たぬき"],["が","が"],["糸車","いとぐるま"],["の","の"],["前","まえ"],["に","に"],["座っていました","すわっていました","座る",15],["。"],["たぬき","たぬき"],["は","は"],["小さな","ちいさな"],["前","まえ"],["の","の"],["足","あし"],["で","で"],["、"],["一生懸命","いっしょうけんめい"],["、"],["糸","いと"],["を","を"],["作っていました","つくっていました","作る",15],["。"]]],"tr":{"az":"Axşamüstü qoca qadın qayıdanda evin içindən çarxın səsini eşitdi. «Görəsən, qoca artıq qayıdıb?» deyə düşündü. Qapını yavaşca açanda tanukinin çarxın qarşısında oturduğunu gördü. Tanuki balaca qabaq pəncələri ilə var gücünü qoyub ip əyirirdi.","en":"When the old woman returned that evening, she heard the spinning wheel inside the house. “Hmm, has the old man come home already?” she wondered. She quietly opened the door and saw the tanuki sitting in front of the wheel. With its tiny front paws, it was working hard to spin thread.","ru":"Когда старушка вернулась вечером, из дома доносился звук прялки. «Хм, неужели старик уже вернулся?» – подумала она. Она тихонько открыла дверь и увидела тануки перед прялкой. Своими маленькими передними лапками он старательно прял нить."}},{"t":[[["たぬき","たぬき"],["が","が"],["作った","つくった","作る",0],["糸","いと"],["は","は"],["、"],["長くて","ながくて","長い",3],["、"],["きれい","きれい"],["でした","でした","です",9],["。"],["おばあさん","おばあさん"],["は","は"],["びっくり","びっくり"],["して","して","する",3],["、"],["「"],["私","わたし"],["より","より"],["上手","じょうず"],["です","です"],["ね","ね"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["たぬき","たぬき"],["は","は"],["うれし","うれし","うれしい"],["そうに","そうに","そう",8],["、"],["くるくる","くるくる"],["回りました","まわりました","回る",2],["。"],["ところ","ところ"],["が","が"],["、"],["回り","まわり","回る",10],["すぎて","すぎて","すぎて",3],["、"],["糸","いと"],["の","の"],["中","なか"],["に","に"],["入ってしまいました","はいってしまいました","入る",14],["。"]]],"tr":{"az":"Tanukinin əyirdiyi ip uzun və gözəl idi. Qoca qadın təəccüblənib «Məndən də yaxşı bacarırsan!» dedi. Tanuki sevinclə fırlanmağa başladı. Amma o qədər çox fırlandı ki, axırda iplərə dolaşdı.","en":"The thread the tanuki had made was long and beautiful. The old woman was surprised. “You're better at this than I am!” she said. The tanuki spun around happily. But it spun so much that it became tangled in the thread.","ru":"Нить, которую спрядал тануки, была длинной и красивой. Старушка удивилась и сказала: «Да ты умеешь лучше меня!» Тануки радостно закружился. Но он так сильно завертелся, что запутался в нитках."}},{"t":[[["「"],["今","いま"],["、"],["助けましょう","たすけましょう","助ける",20],["か","か"],["」"],["と","と"],["、"],["おばあさん","おばあさん"],["は","は"],["聞きました","ききました","聞く",2],["。"],["たぬき","たぬき"],["は","は"],["小さく","ちいさく","小さい"],["頭","あたま"],["を","を"],["下げました","さげました","下げました",2],["。"],["おばあさん","おばあさん"],["は","は"],["眼鏡","めがね"],["を","を"],["掛けて","かけて","掛けて",3],["、"],["糸","いと"],["を","を"],["少し","すこし"],["ずつ","ずつ"],["取りました","とりました","取る",2],["。"],["たぬき","たぬき"],["は","は"],["やっと","やっと"],["自由","じゆう"],["に","に"],["なって","なって","なる",3],["、"],["おばあさん","おばあさん"],["の","の"],["手","て"],["を","を"],["なめました","なめました","なめる",2],["。"]]],"tr":{"az":"«İndi sənə kömək edimmi?» deyə qoca qadın soruşdu. Tanuki başını yüngülcə əydi. Qadın eynəyini taxıb ipləri yavaş-yavaş açdı. Tanuki nəhayət azad oldu və qadının əlini yaladı.","en":"“Shall I help you now?” the old woman asked. The tanuki bowed its little head. The old woman put on her glasses and carefully removed the thread, little by little. At last, the tanuki was free and licked her hand.","ru":"«Давай я тебе помогу?» – спросила старушка. Тануки слегка наклонил голову. Старушка надела очки и стала осторожно распутывать нити. Наконец тануки освободился и лизнул её руку."}},{"t":[[["その","その"],["夜","よる"],["、"],["おじいさん","おじいさん"],["は","は"],["、"],["たぬき","たぬき"],["が","が"],["作った","つくった","作る",0],["糸","いと"],["を","を"],["見ました","みました","見る",2],["。"],["「"],["これ","これ"],["は","は"],["すごい","すごい"],["。"],["明日","あした"],["から","から"],["、"],["私たち","わたしたち"],["も","も"],["手伝いましょう","てつだいましょう","手伝う",20],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["それから","それから"],["、"],["たぬき","たぬき"],["は","は"],["毎日","まいにち"],["、"],["おばあさん","おばあさん"],["と","と"],["一緒","いっしょ"],["に","に"],["糸","いと"],["を","を"],["作りました","つくりました","作る",2],["。"],["村","むら"],["の","の"],["人","ひと"],["は","は"],["、"],["その","その"],["糸","いと"],["で","で"],["作った","つくった","作る",0],["暖かい","あたたかい"],["コート","コート"],["や","や"],["帽子","ぼうし"],["を","を"],["着ました","きました","着る",2],["。"],["たぬき","たぬき"],["は","は"],["村","むら"],["で","で"],["一番","いちばん"],["有名な","ゆうめいな","有名な",1],["糸作り","いとづくり"],["の","の"],["先生","せんせい"],["に","に"],["なりました","なりました","なる",2],["。"]]],"tr":{"az":"Həmin gecə qoca kişi tanukinin əyirdiyi iplərə baxdı. «Bu möhtəşəmdir! Sabahdan biz də ona kömək edək», dedi. O gündən tanuki hər gün qoca qadınla birlikdə ip əyirdi. Kəndlilər həmin ipdən hazırlanan isti paltoları və papaqları geyinirdilər. Tanuki isə kəndin ən məşhur ip əyirmə ustası oldu.","en":"That night, the old man looked at the thread the tanuki had made. “This is wonderful. Let's help too, starting tomorrow,” he said. From then on, the tanuki spun thread with the old woman every day. The villagers wore warm coats and hats made from that thread. The tanuki became the most famous spinning teacher in the village.","ru":"В тот вечер старик посмотрел на нить, которую спрядал тануки. «Вот это чудо! Давай с завтрашнего дня тоже помогать», – сказал он. С тех пор тануки каждый день прял нити вместе со старушкой. Жители деревни носили тёплые пальто и шапки, сделанные из этих нитей. А тануки стал самым знаменитым учителем прядения в деревне."}}]},{"id":"l22b","ti":[[["ようかい","ようかい"],["と","と"],["ふしぎな","ふしぎな","ふしぎ",1],["アパート","アパート"]]],"tt":{"az":"Yokai və sirli mənzil","en":"The Yokai and the Mysterious Apartment","ru":"Ёкай и загадочная квартира"},"P":[{"t":[[["ある","ある","ある(連体詞)"],["町","まち"],["に","に"],["、"],["空","そら"],["と","と"],["いう","いう","いう",5],["名前","なまえ"],["の","の"],["若い","わかい"],["男の子","おとこのこ"],["が","が"],["いました","いました","いる",2],["。"],["空","そら"],["は","は"],["、"],["新しい","あたらしい"],["アパート","アパート"],["を","を"],["探していました","さがしていました","探していました",15],["。"],["学校","がっこう"],["に","に"],["近くて","ちかくて","近い",3],["、"],["家賃","やちん"],["が","が"],["安い","やすい"],["部屋","へや"],["が","が"],["欲しかった","ほしかった","欲しい",0],["の","の"],["です","です"],["。"],["ある日","あるひ"],["、"],["空","そら"],["は","は"],["古い","ふるい"],["アパート","アパート"],["を","を"],["見つけました","みつけました","見つける",2],["。"],["その","その"],["アパート","アパート"],["に","に"],["は","は"],["、"],["大きな","おおきな"],["窓","まど"],["が","が"],["ある","ある","ある(連体詞)"],["部屋","へや"],["が","が"],["ありました","ありました","ある",2],["。"]]],"tr":{"az":"Bir şəhərdə Sora adlı gənc oğlan yaşayırdı. Sora yeni mənzil axtarırdı. O, məktəbə yaxın və kirayəsi ucuz bir otaq istəyirdi. Bir gün köhnə bir yaşayış binası tapdı. Həmin binada böyük pəncərəsi olan bir otaq var idi.","en":"In a certain town, there lived a young boy named Sora. Sora was looking for a new apartment. He wanted a room close to school with low rent. One day, he found an old apartment building. It had a room with a large window.","ru":"В одном городе жил молодой парень по имени Сора. Он искал новую квартиру. Ему нужна была комната рядом со школой с невысокой арендной платой. Однажды он нашёл старый многоквартирный дом. Там была комната с большим окном."}},{"t":[[["部屋","へや"],["に","に"],["入る","はいる","入る",5],["と","と"],["、"],["白い","しろい"],["帽子","ぼうし"],["を","を"],["被った","かぶった","被った",0],["小さな","ちいさな"],["男の子","おとこのこ"],["が","が"],["いました","いました","いる",2],["。"],["その","その"],["子","こ"],["は","は"],["青い","あおい"],["セーター","セーター"],["を","を"],["着て","きて","着る",3],["、"],["赤い","あかい"],["靴","くつ"],["を","を"],["履いていました","はいていました","履く",15],["。"],["「"],["ぼく","ぼく"],["は","は"],["モチ","モチ"],["。"],["ここ","ここ"],["に","に"],["住んでいる","すんでいる","住む",45],["ようかい","ようかい"],["だ","だ","です"],["よ","よ"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["空","そら"],["は","は"],["驚きました","おどろきました","驚く",2],["が","が"],["、"],["モチ","モチ"],["は","は"],["とても","とても"],["かわいい","かわいい"],["顔","かお"],["を","を"],["していました","していました","する",15],["。"]]],"tr":{"az":"Otağa girəndə ağ papaq taxmış balaca bir oğlan gördü. Uşaq mavi sviter geyinmiş, qırmızı ayaqqabı taxmışdı. «Mən Moçiyəm. Burada yaşayan yokaiyəm», dedi. Sora təəccübləndi, amma Moçinin çox şirin üzü var idi.","en":"When he entered the room, he saw a little boy wearing a white hat. The boy had on a blue sweater and red shoes. “I'm Mochi. I'm a yokai who lives here,” he said. Sora was surprised, but Mochi had a very cute face.","ru":"Когда он вошёл в комнату, то увидел маленького мальчика в белой шапке. На мальчике были синий свитер и красные ботинки. «Я Моти. Я ёкай, который здесь живёт», – сказал он. Сора удивился, но у Моти было очень милое лицо."}},{"t":[[["モチ","モチ"],["は","は"],["「"],["私たち","わたしたち"],["、"],["一緒","いっしょ"],["に","に"],["住もう","すもう","住む",7],["よ","よ"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["空","そら"],["は","は"],["少し","すこし"],["考えて","かんがえて","考える",3],["、"],["「"],["いい","いい"],["よ","よ"],["。"],["でも","でも"],["、"],["夜","よる"],["は","は"],["静かに","しずかに","静か",8],["して","して","する",3],["ね","ね"],["」"],["と","と"],["答えました","こたえました","答える",2],["。"],["モチ","モチ"],["は","は"],["大きく","おおきく","大きい"],["うなずきました","うなずきました","うなずく",2],["。"],["その","その"],["夜","よる"],["、"],["二人","ふたり"],["は","は"],["一緒","いっしょ"],["に","に"],["住む","すむ","住む",5],["約束","やくそく"],["を","を"],["しました","しました","する",2],["。"],["空","そら"],["は","は"],["、"],["ようかい","ようかい"],["と","と"],["住む","すむ","住む",5],["生活","せいかつ"],["を","を"],["楽しみ","たのしみ"],["に","に"],["していました","していました","する",15],["。"]]],"tr":{"az":"Moçi «Gəl birlikdə yaşayaq!» dedi. Sora bir az düşünüb «Olar. Amma gecələr sakit ol, yaxşı?» deyə cavab verdi. Moçi başını həvəslə yellədi. Həmin gecə ikisi birlikdə yaşamağa söz verdilər. Sora yokai ilə yaşayacağı günləri səbirsizliklə gözləyirdi.","en":"“Let's live together!” Mochi said. Sora thought for a moment. “All right. But please be quiet at night,” he replied. Mochi nodded eagerly. That night, the two promised to live together. Sora was looking forward to life with a yokai.","ru":"«Давай жить вместе!» – предложил Моти. Сора немного подумал и ответил: «Хорошо. Но ночью, пожалуйста, не шуми». Моти энергично кивнул. В тот вечер они договорились жить вместе. Сора с нетерпением ждал жизни с ёкаем."}},{"t":[[["次","つぎ"],["の","の"],["日","ひ"],["、"],["空","そら"],["が","が"],["学校","がっこう"],["へ","へ"],["行く","いく","行く",5],["時間","じかん"],["に","に"],["なりました","なりました","なる",2],["。"],["でも","でも"],["、"],["空","そら"],["の","の"],["眼鏡","めがね"],["が","が"],["ありませんでした","ありませんでした","ある",4],["。"],["「"],["モチ","モチ"],["、"],["眼鏡","めがね"],["を","を"],["見なかった","みなかった","見る",22],["？"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"],["モチ","モチ"],["は","は"],["「"],["ええ","ええ"],["と","と"],["、"],["昨日","きのう"],["、"],["机","つくえ"],["の","の"],["上","うえ"],["に","に"],["あった","あった","ある",0],["よ","よ"],["」"],["と","と"],["答えました","こたえました","答える",2],["。"],["二人","ふたり"],["が","が"],["探している","さがしている","探している",26],["眼鏡","めがね"],["は","は"],["、"],["なん","なん"],["と","と"],["、"],["冷蔵庫","れいぞうこ"],["の","の"],["中","なか"],["に","に"],["ありました","ありました","ある",2],["。"]]],"tr":{"az":"Ertəsi gün Soranın məktəbə getmək vaxtı çatdı. Amma eynəyi yox idi. «Moçi, eynəyimi görməmisən?» deyə soruşdu. Moçi «Hmm, dünən masanın üstündə idi», dedi. İkisinin axtardığı eynək, inanılmaz olsa da, soyuducunun içindən çıxdı.","en":"The next day, it was time for Sora to go to school. But his glasses were missing. “Mochi, have you seen my glasses?” he asked. “Hmm, they were on the desk yesterday,” Mochi answered. Amazingly, the glasses they were looking for were inside the refrigerator.","ru":"На следующий день Соре пора было идти в школу. Но его очки пропали. «Моти, ты не видел мои очки?» – спросил он. «Хм, вчера они лежали на столе», – ответил Моти. Удивительно, но очки, которые они искали, оказались в холодильнике."}},{"t":[[["その","その"],["日","ひ"],["の","の"],["夜","よる"],["、"],["空","そら"],["は","は"],["お弁当","おべんとう"],["を","を"],["作る","つくる","作る",5],["用事","ようじ"],["が","が"],["ありました","ありました","ある",2],["。"],["台所","だいどころ"],["へ","へ"],["行く","いく","行く",5],["と","と"],["、"],["お弁当","おべんとう"],["の","の"],["箱","はこ"],["が","が"],["ありませんでした","ありませんでした","ある",4],["。"],["モチ","モチ"],["は","は"],["「"],["一緒","いっしょ"],["に","に"],["探しましょう","さがしましょう","探しましょう",20],["か","か"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["二人","ふたり"],["が","が"],["見つけた","みつけた","見つける",0],["箱","はこ"],["は","は"],["、"],["なん","なん"],["と","と"],["、"],["空","そら"],["の","の"],["ベッド","ベッド"],["の","の"],["下","した"],["に","に"],["ありました","ありました","ある",2],["。"],["モチ","モチ"],["は","は"],["「"],["ぼく","ぼく"],["の","の"],["魔法","まほう"],["は","は"],["、"],["時々","ときどき"],["、"],["変な","へんな","変",1],["ん","ん"],["だ","だ","です"],["」"],["と","と"],["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Həmin axşam Sora sabah üçün bentō hazırlamalı idi. Mətbəxə gedəndə yemək qutusunun yerində olmadığını gördü. Moçi «Birlikdə axtaraq?» dedi. Tapdıqları qutu, inanılmaz olsa da, Soranın çarpayısının altında idi. Moçi gülərək «Mənim sehrim bəzən qəribə işləyir», dedi.","en":"That evening, Sora had to make a packed lunch. When he went to the kitchen, his lunch box was missing. “Shall we look for it together?” Mochi asked. Amazingly, the box they found was under Sora's bed. “My magic acts strangely sometimes,” Mochi said with a laugh.","ru":"В тот вечер Соре нужно было приготовить бэнто. Когда он пришёл на кухню, коробки для обеда не оказалось на месте. «Давай поищем вместе?» – предложил Моти. Удивительно, но коробка нашлась под кроватью Соры. «Моя магия иногда работает странно», – рассмеялся Моти."}},{"t":[[["ある日","あるひ"],["、"],["空","そら"],["の","の"],["友達","ともだち"],["が","が"],["遊び","あそび","遊ぶ",10],["に","に"],["来る","くる","来る",5],["約束","やくそく"],["を","を"],["しました","しました","する",2],["。"],["空","そら"],["は","は"],["モチ","モチ"],["に","に"],["、"],["「"],["今日","きょう"],["は","は"],["友達","ともだち"],["が","が"],["来る","くる","来る",5],["から","から"],["、"],["魔法","まほう"],["を","を"],["使わないで","つかわないで","使う",18],["ね","ね"],["」"],["と","と"],["頼みました","たのみました","頼む",2],["。"],["モチ","モチ"],["は","は"],["「"],["うん","うん"],["、"],["わかった","わかった","わかる",0],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["でも","でも"],["、"],["友達","ともだち"],["が","が"],["来る","くる","来る",5],["と","と"],["、"],["テーブル","テーブル"],["の","の"],["上","うえ"],["の","の"],["ケーキ","ケーキ"],["が","が"],["空","そら"],["を","を"],["飛びました","とびました","飛ぶ",2],["。"],["友達","ともだち"],["は","は"],["「"],["すごい","すごい"],["ロボット","ロボット"],["だ","だ","です"],["ね","ね"],["！"],["」"],["と","と"],["喜びました","よろこびました","喜ぶ",2],["。"]]],"tr":{"az":"Bir gün Soranın dostu qonaq gəlməyə söz verdi. Sora Moçidən «Bu gün dostum gələcək, xahiş edirəm, sehr işlətmə», deyə xahiş etdi. Moçi «Hə, başa düşdüm», dedi. Amma dostu gələn kimi masanın üstündəki tort havada uçmağa başladı. Dostu sevinərək «Necə də möhtəşəm robotdur!» dedi.","en":"One day, Sora made plans for a friend to visit. “My friend is coming today, so please don't use magic,” Sora asked Mochi. “Okay, I understand,” Mochi replied. But when the friend arrived, the cake on the table began flying through the air. “What an amazing robot!” the friend exclaimed happily.","ru":"Однажды друг Соры договорился прийти в гости. «Сегодня придёт мой друг, поэтому, пожалуйста, не используй магию», – попросил Сора Моти. «Ага, понял», – ответил Моти. Но когда друг пришёл, торт на столе вдруг взлетел в воздух. «Какой удивительный робот!» – радостно воскликнул друг."}},{"t":[[["空","そら"],["は","は"],["困りました","こまりました","困る",2],["が","が"],["、"],["モチ","モチ"],["は","は"],["楽し","たのし","楽しい"],["そう","そう"],["でした","でした","です",9],["。"],["モチ","モチ"],["が","が"],["作った","つくった","作る",0],["小さな","ちいさな"],["雲","くも"],["から","から"],["、"],["甘い","あまい"],["お菓子","おかし"],["が","が"],["降ってきました","ふってきました","降る",23],["。"],["友達","ともだち"],["は","は"],["「"],["この","この"],["アパート","アパート"],["は","は"],["本当","ほんとう"],["に","に"],["楽しい","たのしい"],["ね","ね"],["」"],["と","と"],["笑いました","わらいました","笑う",2],["。"],["モチ","モチ"],["は","は"],["「"],["ぼく","ぼく"],["に","に"],["は","は"],["ユーモア","ユーモア"],["が","が"],["ある","ある","ある",5],["ん","ん"],["だ","だ","です"],["よ","よ"],["」"],["と","と"],["胸","むね"],["を","を"],["張りました","はりました","張る",2],["。"]]],"tr":{"az":"Sora nə edəcəyini bilmirdi, amma Moçi çox əylənirdi. Moçinin yaratdığı balaca buluddan şirin konfetlər yağmağa başladı. Dostu gülərək «Bu mənzil həqiqətən çox əyləncəlidir!» dedi. Moçi qürurla sinəsini qabağa verib «Mənim yumor hissim var!» söylədi.","en":"Sora didn't know what to do, but Mochi was having fun. Sweet candies began falling from a little cloud Mochi had made. “This apartment really is fun!” the friend said, laughing. Mochi puffed out his chest proudly. “I've got a sense of humor!” he declared.","ru":"Сора растерялся, а Моти веселился. Из маленького облака, которое создал Моти, посыпались сладкие конфеты. «Какая же весёлая у тебя квартира!» – рассмеялся друг. Моти гордо выпятил грудь и заявил: «У меня отличное чувство юмора!»"}},{"t":[[["それから","それから"],["、"],["空","そら"],["の","の"],["部屋","へや"],["に","に"],["は","は"],["毎日","まいにち"],["、"],["友達","ともだち"],["が","が"],["来ました","きました","来る",2],["。"],["モチ","モチ"],["は","は"],["、"],["みんな","みんな"],["が","が"],["笑う","わらう","笑う",5],["魔法","まほう"],["を","を"],["たくさん","たくさん"],["見せました","みせました","見せる",2],["。"],["ある","ある","ある(連体詞)"],["朝","あさ"],["、"],["空","そら"],["が","が"],["起きる","おきる","起きる",5],["と","と"],["、"],["部屋","へや"],["の","の"],["中","なか"],["に","に"],["小さな","ちいさな"],["虹","にじ"],["が","が"],["ありました","ありました","ある",2],["。"],["虹","にじ"],["の","の"],["下","した"],["に","に"],["は","は"],["、"],["「"],["私たち","わたしたち"],["の","の"],["家","いえ"],["」"],["と","と"],["いう","いう","いう",5],["紙","かみ"],["が","が"],["ありました","ありました","ある",2],["。"],["空","そら"],["は","は"],["その","その"],["紙","かみ"],["を","を"],["見て","みて","見る",3],["、"],["幸せな","しあわせな","幸せ",1],["気持ち","きもち"],["に","に"],["なりました","なりました","なる",2],["。"]]],"tr":{"az":"O gündən sonra Soranın otağına hər gün dostları gəlirdi. Moçi hamını güldürən çoxlu sehrlər göstərirdi. Bir səhər Sora oyananda otaqda balaca göy qurşağı gördü. Göy qurşağının altında «Bizim evimiz» yazılmış bir kağız var idi. Sora kağıza baxıb özünü çox xoşbəxt hiss etdi.","en":"From then on, friends visited Sora's room every day. Mochi showed them lots of magic tricks that made everyone laugh. One morning, Sora woke up and found a little rainbow in the room. Beneath the rainbow was a piece of paper that said, “Our Home.” When Sora saw it, he felt very happy.","ru":"С тех пор друзья каждый день приходили к Соре. Моти показывал им множество волшебных фокусов, которые всех смешили. Однажды утром Сора проснулся и увидел в комнате маленькую радугу. Под радугой лежал листок с надписью «Наш дом». Увидев его, Сора почувствовал себя очень счастливым."}}]},{"id":"l22c","ti":[[["おばあちゃん","おばあちゃん"],["が","が"],["探した","さがした","探した",0],["部屋","へや"]]],"tt":{"az":"Nənənin axtardığı mənzil","en":"The Apartment Grandma Was Looking For","ru":"Квартира, которую искала бабушка"},"P":[{"t":[[["ある","ある","ある(連体詞)"],["町","まち"],["に","に"],["、"],["花","はな"],["と","と"],["いう","いう","いう",5],["女の子","おんなのこ"],["が","が"],["いました","いました","いる",2],["。"],["花","はな"],["の","の"],["おばあさん","おばあさん"],["は","は"],["、"],["長い","ながい"],["間","あいだ"],["、"],["田舎","いなか"],["に","に"],["住んでいました","すんでいました","住む",31],["。"],["ある日","あるひ"],["、"],["おばあさん","おばあさん"],["は","は"],["「"],["町","まち"],["で","で"],["新しい","あたらしい"],["部屋","へや"],["を","を"],["探したい","さがしたい","探したい",30],["です","です"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["花","はな"],["は","は"],["「"],["私たち","わたしたち"],["も","も"],["一緒","いっしょ"],["に","に"],["探しましょう","さがしましょう","探しましょう",20],["か","か"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"],["おばあさん","おばあさん"],["は","は"],["うれし","うれし","うれしい"],["そうに","そうに","そう",8],["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Bir şəhərdə Hana adlı qız yaşayırdı. Hananın nənəsi uzun müddət kənddə yaşamışdı. Bir gün nənəsi «Şəhərdə yeni mənzil axtarmaq istəyirəm», dedi. Hana «Biz də səninlə birlikdə axtaraq?» deyə soruşdu. Nənəsi sevinclə gülümsədi.","en":"In a certain town, there was a girl named Hana. Hana's grandmother had lived in the countryside for a long time. One day, Grandma said, “I want to look for a new apartment in town.” “Shall we help you look?” Hana asked. Grandma smiled happily.","ru":"В одном городе жила девочка по имени Хана. Её бабушка долгое время жила в деревне. Однажды бабушка сказала: «Я хочу найти новую квартиру в городе». «Может, мы тоже поможем тебе искать?» – спросила Хана. Бабушка радостно улыбнулась."}},{"t":[[["次","つぎ"],["の","の"],["日","ひ"],["、"],["花","はな"],["は","は"],["おばあさん","おばあさん"],["が","が"],["住みたい","すみたい","住む",30],["部屋","へや"],["に","に"],["ついて","ついて","つく",3],["聞きました","ききました","聞く",2],["。"],["おばあさん","おばあさん"],["は","は"],["「"],["大きな","おおきな"],["窓","まど"],["が","が"],["ある","ある","ある(連体詞)"],["部屋","へや"],["が","が"],["いい","いい"],["です","です"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["「"],["それから","それから"],["、"],["駅","えき"],["に","に"],["近い","ちかい"],["家","いえ"],["が","が"],["いい","いい"],["です","です"],["ね","ね"],["」"],["と","と"],["続けました","つづけました","続けました",2],["。"],["花","はな"],["は","は"],["ノート","ノート"],["に","に"],["、"],["おばあさん","おばあさん"],["が","が"],["欲しい","ほしい"],["部屋","へや"],["の","の"],["こと","こと"],["を","を"],["書きました","かきました","書く",2],["。"]]],"tr":{"az":"Ertəsi gün Hana nənəsinin necə bir mənzildə yaşamaq istədiyini soruşdu. Nənəsi «Böyük pəncərəsi olan otaq yaxşı olar», dedi. Sonra «Bir də stansiyaya yaxın ev istəyirəm», deyə əlavə etdi. Hana nənəsinin istədiyi mənzilin xüsusiyyətlərini dəftərinə yazdı.","en":"The next day, Hana asked what kind of apartment Grandma wanted to live in. “I'd like a room with a big window,” Grandma said. “And a home close to the station would be nice,” she added. Hana wrote down the details of the apartment Grandma wanted in her notebook.","ru":"На следующий день Хана спросила, в какой квартире бабушка хотела бы жить. «Мне нужна комната с большим окном», – сказала бабушка. «И ещё хорошо бы жить недалеко от станции», – добавила она. Хана записала в блокнот всё, что бабушка хотела видеть в новой квартире."}},{"t":[[["土曜","どよう"],["日","ひ"],["、"],["二人","ふたり"],["は","は"],["不動産屋","ふどうさんや"],["へ","へ"],["行く","いく","行く",5],["約束","やくそく"],["を","を"],["しました","しました","する",2],["。"],["でも","でも"],["、"],["朝","あさ"],["から","から"],["雨","あめ"],["が","が"],["降っていました","ふっていました","降る",15],["。"],["おばあさん","おばあさん"],["は","は"],["暖かい","あたたかい"],["コート","コート"],["を","を"],["着て","きて","着る",3],["、"],["帽子","ぼうし"],["を","を"],["被りました","かぶりました","被りました",2],["。"],["花","はな"],["は","は"],["赤い","あかい"],["セーター","セーター"],["を","を"],["着ました","きました","着る",2],["。"],["「"],["で","で"],["は","は"],["、"],["行きましょう","いきましょう","行く",20],["」"],["と","と"],["、"],["おばあさん","おばあさん"],["は","は"],["元気","げんき"],["に","に"],["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Şənbə günü ikisi daşınmaz əmlak agentliyinə getməyi qərarlaşdırdı. Amma səhərdən yağış yağırdı. Nənəsi isti palto geyinib papağını taxdı. Hana qırmızı sviter geyindi. «Elə isə gedək!» deyə nənəsi həvəslə səsləndi.","en":"They made an appointment to visit the real estate agency on Saturday. But it had been raining since morning. Grandma put on a warm coat and a hat. Hana wore a red sweater. “Well then, let's go!” Grandma said cheerfully.","ru":"Они договорились пойти в агентство недвижимости в субботу. Но с самого утра шёл дождь. Бабушка надела тёплое пальто и шапку. Хана надела красный свитер. «Ну что ж, пойдём!» – бодро сказала бабушка."}},{"t":[[["不動産屋","ふどうさんや"],["に","に"],["は","は"],["、"],["眼鏡","めがね"],["を","を"],["掛けた","かけた","掛けた",0],["親切な","しんせつな","親切",1],["男","おとこ"],["の","の"],["人","ひと"],["が","が"],["いました","いました","いる",2],["。"],["その","その"],["人","ひと"],["は","は"],["二人","ふたり"],["に","に"],["、"],["三つ","みっつ"],["の","の"],["部屋","へや"],["を","を"],["見せました","みせました","見せる",2],["。"],["一つ目","ひとつめ"],["は","は"],["新しくて","あたらしくて","新しい",3],["、"],["きれいな","きれいな","きれい",1],["部屋","へや"],["でした","でした","です",9],["。"],["でも","でも"],["、"],["窓","まど"],["が","が"],["小さかった","ちいさかった","小さい",0],["です","です"],["。"],["二つ目","ふたつめ"],["は","は"],["駅","えき"],["に","に"],["近い","ちかい"],["部屋","へや"],["でした","でした","です",9],["が","が"],["、"],["とても","とても"],["暗かった","くらかった","暗い",0],["です","です"],["。"]]],"tr":{"az":"Əmlak agentliyində eynək taxmış mehriban bir kişi var idi. O, onlara üç mənzil göstərdi. Birincisi yeni və təmiz idi. Amma pəncərəsi balaca idi. İkinci mənzil stansiyaya yaxın idi, lakin çox qaranlıq idi.","en":"At the real estate agency, there was a kind man wearing glasses. He showed them three apartments. The first one was new and clean. But it had small windows. The second apartment was near the station, but it was very dark.","ru":"В агентстве недвижимости работал добрый мужчина в очках. Он показал им три квартиры. Первая была новой и чистой. Но окна в ней были маленькими. Вторая квартира находилась рядом со станцией, однако в ней было очень темно."}},{"t":[[["三つ目","みっつめ"],["は","は"],["古い","ふるい"],["アパート","アパート"],["の","の"],["一階","いちかい"],["に","に"],["ある","ある","ある(連体詞)"],["部屋","へや"],["でした","でした","です",9],["。"],["そこ","そこ"],["に","に"],["は","は"],["、"],["大きな","おおきな"],["窓","まど"],["と","と"],["小さな","ちいさな"],["庭","にわ"],["が","が"],["ありました","ありました","ある",2],["。"],["庭","にわ"],["に","に"],["は","は"],["、"],["花","はな"],["が","が"],["たくさん","たくさん"],["咲いていました","さいていました","咲く",15],["。"],["おばあさん","おばあさん"],["は","は"],["窓","まど"],["の","の"],["外","そと"],["を","を"],["見て","みて","見る",3],["、"],["にこにこ","にこにこ"],["しました","しました","する",2],["。"],["「"],["ここ","ここ"],["は","は"],["、"],["私","わたし"],["が","が"],["生まれた","うまれた","生まれた",0],["村","むら"],["に","に"],["少し","すこし"],["似ています","にています","似ています",24],["」"],["と","と"],["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Üçüncü mənzil köhnə binanın birinci mərtəbəsində idi. Orada böyük pəncərə və balaca bağ var idi. Bağda çoxlu güllər açmışdı. Nənəsi pəncərədən baxıb gülümsədi. «Bura mənim doğulduğum kəndə bir az oxşayır», dedi.","en":"The third apartment was on the ground floor of an old building. It had a large window and a small garden. Many flowers were blooming in the garden. Grandma looked out the window and smiled. “This place looks a little like the village where I was born,” she said.","ru":"Третья квартира находилась на первом этаже старого дома. В ней было большое окно, а рядом был маленький сад. В саду цвело много цветов. Бабушка посмотрела в окно и улыбнулась. «Это место немного напоминает деревню, где я родилась», – сказала она."}},{"t":[[["花","はな"],["は","は"],["「"],["この","この"],["部屋","へや"],["が","が"],["一番","いちばん"],["いい","いい"],["です","です"],["ね","ね"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["でも","でも"],["、"],["おばあさん","おばあさん"],["は","は"],["すぐ","すぐ"],["に","に"],["答えませんでした","こたえませんでした","答える",4],["。"],["「"],["ええ","ええ"],["と","と"],["、"],["今日","きょう"],["は","は"],["まだ","まだ"],["用事","ようじ"],["が","が"],["あります","あります","ある",11],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["そして","そして"],["、"],["「"],["日曜","にちよう"],["日","ひ"],["の","の"],["午後","ごご"],["、"],["もう","もう"],["一度","いちど"],["ここ","ここ"],["に","に"],["来る","くる","来る",5],["約束","やくそく"],["を","を"],["しましょう","しましょう","する",20],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["花","はな"],["は","は"],["、"],["どう","どう"],["して","して","する",3],["もう","もう"],["一度","いちど"],["来る","くる","来る",5],["の","の"],["か","か"],["、"],["わかりませんでした","わかりませんでした","わかる",4],["。"]]],"tr":{"az":"Hana «Məncə, ən yaxşısı bu mənzildir», dedi. Amma nənəsi dərhal cavab vermədi. «Hmm, bu gün hələ başqa işim də var», dedi. Sonra «Bazar günü günortadan sonra bura yenidən gəlmək üçün görüş təyin edək», söylədi. Hana nənəsinin niyə bir də gəlmək istədiyini başa düşmədi.","en":"“I think this apartment is the best,” Hana said. But Grandma didn't answer right away. “Hmm, I still have something to do today,” she said. Then she added, “Let's make an appointment to come here again on Sunday afternoon.” Hana couldn't understand why Grandma wanted to return.","ru":"«По-моему, эта квартира самая лучшая», – сказала Хана. Но бабушка ответила не сразу. «Хм, у меня сегодня ещё есть дела», – сказала она. Затем добавила: «Давай договоримся прийти сюда ещё раз в воскресенье после обеда». Хана не понимала, зачем бабушка хотела вернуться."}},{"t":[[["日曜","にちよう"],["日","ひ"],["、"],["花","はな"],["と","と"],["おばあさん","おばあさん"],["は","は"],["、"],["また","また"],["その","その"],["部屋","へや"],["へ","へ"],["行きました","いきました","行く",2],["。"],["する","する","する",5],["と","と"],["、"],["庭","にわ"],["に","に"],["小さな","ちいさな"],["テーブル","テーブル"],["が","が"],["ありました","ありました","ある",2],["。"],["テーブル","テーブル"],["の","の"],["上","うえ"],["に","に"],["は","は"],["、"],["花","はな"],["が","が"],["好きな","すきな","好き",1],["ケーキ","ケーキ"],["が","が"],["ありました","ありました","ある",2],["。"],["近く","ちかく"],["に","に"],["は","は"],["、"],["スーツ","スーツ"],["を","を"],["着た","きた","着る",0],["おじいさん","おじいさん"],["と","と"],["、"],["花","はな"],["の","の"],["お父さん","おとうさん"],["と","と"],["お母さん","おかあさん"],["が","が"],["いました","いました","いる",2],["。"],["みんな","みんな"],["、"],["にこにこ","にこにこ"],["していました","していました","する",15],["。"]]],"tr":{"az":"Bazar günü Hana ilə nənəsi həmin mənzilə yenidən getdilər. Bu dəfə bağda balaca masa var idi. Masanın üstündə Hananın sevdiyi tort qoyulmuşdu. Yaxınlıqda kostyum geyinmiş babası, Hananın atası və anası dayanmışdı. Hamısı gülümsəyirdi.","en":"On Sunday, Hana and Grandma returned to the apartment. This time, a little table stood in the garden. On the table was Hana's favorite cake. Nearby stood Grandpa, wearing a suit, along with Hana's father and mother. Everyone was smiling.","ru":"В воскресенье Хана с бабушкой снова пришли в ту квартиру. На этот раз в саду стоял маленький стол. На столе был любимый торт Ханы. Рядом стояли дедушка в костюме, папа и мама Ханы. Все улыбались."}},{"t":[[["「"],["花ちゃん","はなちゃん"],["、"],["お誕生","おたんじょう"],["日","ひ"],["おめでとう","おめでとう","おめでたい"],["ございます","ございます","ござる",11],["！"],["」"],["と","と"],["、"],["みんな","みんな"],["が","が"],["言いました","いいました","言う",2],["。"],["おばあさん","おばあさん"],["は","は"],["「"],["本当","ほんとう"],["は","は"],["、"],["この","この"],["部屋","へや"],["を","を"],["探していた","さがしていた","探していた",47],["の","の"],["は","は"],["、"],["あなた","あなた"],["の","の"],["ため","ため"],["です","です"],["よ","よ"],["」"],["と","と"],["笑いました","わらいました","笑う",2],["。"],["家族","かぞく"],["が","が"],["一緒","いっしょ"],["に","に"],["集まる","あつまる","集まる",5],["場所","ばしょ"],["が","が"],["欲しかった","ほしかった","欲しい",0],["の","の"],["です","です"],["。"],["花","はな"],["は","は"],["びっくり","びっくり"],["して","して","する",3],["、"],["うれしくて","うれしくて","うれしい",3],["泣きました","なきました","泣く",2],["。"],["それから","それから"],["、"],["その","その"],["小さな","ちいさな"],["庭","にわ"],["は","は"],["、"],["家族","かぞく"],["が","が"],["よく","よく"],["集まる","あつまる","集まる",5],["大切な","たいせつな","大切",1],["場所","ばしょ"],["に","に"],["なりました","なりました","なる",2],["。"]]],"tr":{"az":"«Hana, ad günün mübarək!» deyə hamı birlikdə səsləndi. Nənəsi gülümsəyərək «Əslində, bu mənzili sənin üçün axtarırdım», dedi. O, bütün ailənin bir yerə toplaşa biləcəyi məkan istəyirdi. Hana təəccübündən və sevincindən ağladı. O gündən sonra balaca bağ ailənin tez-tez toplandığı əziz bir yerə çevrildi.","en":"“Happy birthday, Hana!” everyone called out together. Grandma smiled. “Actually, I was looking for this apartment for you,” she said. She had wanted a place where the whole family could gather. Hana was so surprised and happy that she cried. From then on, the little garden became a treasured place where the family often met.","ru":"«Хана, с днём рождения!» – хором воскликнули все. Бабушка улыбнулась и сказала: «На самом деле я искала эту квартиру ради тебя». Она хотела найти место, где могла бы собираться вся семья. Хана так удивилась и обрадовалась, что заплакала. С тех пор маленький сад стал дорогим для всех местом, где семья часто собиралась."}}]}],"G":{"あなた":{"b":"あなた","p":"pr","m":{"az":"sən, siz","en":"you","ru":"ты, вы"},"n":{"az":"Yaponcada adamı adı ilə çağırmaq daha nəzakətlidir (ケンさん). あなた bəzən soyuq səslənir.","en":"Calling people by name (ケンさん) is more polite; あなた can sound cold.","ru":"Вежливее обращаться по имени (ケンさん); あなた может звучать холодно."}},"ある":{"b":"ある","p":"v","m":{"az":"olmaq, var olmaq (cansız şeylər)","en":"to be, to exist (things)","ru":"быть, иметься (о предметах)"},"n":{"az":"Cansız şeylər üçün: 電池がありました = batareya var idi. Canlılar üçün いる. 書いてありました = yazılmışdı (yazılı vəziyyətdə idi).","en":"For non-living things: 電池がありました = there was a battery. For living things use いる. 書いてありました = was written (and stayed so).","ru":"Для неодушевлённых: 電池がありました = была батарейка. Для живых – いる. 書いてありました = было написано."}},"ある(連体詞)":{"b":"ある","p":"dm","m":{"az":"bir, hansısa (bir)","en":"a certain, one","ru":"некий, один"},"n":{"az":"ある朝 = bir səhər; ある日 = bir gün. İsimdən əvvəl gələndə 'var olmaq' feili deyil.","en":"ある朝 = one morning. Before a noun it is not the verb 'to exist'.","ru":"ある朝 = однажды утром. Перед существительным это не глагол 'быть'."}},"ある日":{"b":"ある日 (あるひ)","p":"ex","m":{"az":"bir gün","en":"one day","ru":"однажды"}},"いい":{"b":"いい・良い (よい)","p":"ai","m":{"az":"yaxşı","en":"good","ru":"хороший"},"n":{"az":"İ-sifətdir, lakin dəyişən formaları よい əsasından yaranır: よくない, よかった.","en":"An i-adjective whose inflected forms use よい: よくない, よかった.","ru":"И-прилагательное, изменяемые формы которого образуются от よい: よくない, よかった."}},"いう":{"b":"という","p":"ex","m":{"az":"adlı, deyilən","en":"called, named","ru":"под названием"},"n":{"az":"N という名前 = N adlı ad: 「かぐや」という名前 = «Kaquya» adı.","en":"N という名前 = the name \"N\".","ru":"N という名前 = имя «N»."}},"いる":{"b":"いる","p":"v","m":{"az":"olmaq, var olmaq (canlılar); yaşamaq","en":"to be, exist (living things)","ru":"быть, находиться (о живых)"},"n":{"az":"Canlılar üçün: 女の子がいました = bir qız var idi. 〜ている = davam edən hal.","en":"For living things: 女の子がいました = there was a girl. 〜ている = continuous.","ru":"Для живых: 女の子がいました = была девочка. 〜ている – длительный вид."}},"うなずく":{"b":"うなずく","p":"v","m":{"az":"başını tərpədərək təsdiqləmək","en":"to nod","ru":"кивать головой"},"n":{"az":"Razılıq və ya başa düşməyi baş hərəkəti ilə bildirir.","en":"Expresses agreement or understanding by nodding.","ru":"Выражает согласие или понимание кивком головы."}},"うれしい":{"b":"嬉しい (うれしい)","p":"ai","m":{"az":"sevincli, şad","en":"happy, glad","ru":"радостный, довольный"},"n":{"az":"い sifətidir, うれし bağlayıcı və ya başqa forma yaratmaq üçün əsasdır.","en":"An i-adjective, with うれし as the stem used to form other expressions.","ru":"Прилагательное на い, うれし - основа для образования других форм."}},"うん":{"b":"うん","p":"in","m":{"az":"hə, bəli","en":"yeah, yes","ru":"ага, да"},"n":{"az":"はい sözünün qeyri-rəsmi qarşılığıdır.","en":"It is an informal equivalent of はい.","ru":"Это неформальный вариант はい."}},"ええ":{"b":"ええ","p":"in","m":{"az":"bəli; hə","en":"yes","ru":"да"},"n":{"az":"Danışıqda işlənən təsdiqdir, はい-dan daha az rəsmidir.","en":"A conversational yes, less formal than はい.","ru":"Разговорное «да», менее официальное, чем はい."}},"おじいさん":{"b":"おじいさん","p":"n","m":{"az":"baba; qoca kişi","en":"grandfather; old man","ru":"дедушка; старик"}},"おばあさん":{"b":"おばあさん","p":"n","m":{"az":"nənə; qarı","en":"grandmother; old woman","ru":"бабушка; старушка"}},"おばあちゃん":{"b":"おばあちゃん","p":"n","m":{"az":"nənə; yaşlı qadın","en":"grandma; elderly woman","ru":"бабушка; пожилая женщина"},"n":{"az":"Nənəyə və ya yaşlı qadına mehriban müraciət kimi də işlənir.","en":"Also used as an affectionate address to a grandmother or elderly woman.","ru":"Также используется как ласковое обращение к бабушке или пожилой женщине."}},"おめでたい":{"b":"おめでたい","p":"ai","m":{"az":"əlamətdar, sevindirici","en":"auspicious, joyous","ru":"знаменательный, радостный"},"n":{"az":"İ-sifətidir; おめでとう təbrik ifadəsidir və “Təbrik edirəm!” deməkdir.","en":"An i-adjective; おめでとう is the greeting “Congratulations!” derived from it.","ru":"Прилагательное на い; производная форма おめでとう означает «Поздравляю!»."}},"お母さん":{"b":"お母さん (おかあさん)","p":"n","m":{"az":"ana","en":"mother; mom","ru":"мама; мать"},"n":{"az":"Anaya müraciətdə və başqasının anası haqqında işlənir; kənar şəxslərə öz anandan danışarkən adətən 母 deyilir.","en":"Used to address your mother or refer to someone else's; use 母 for your own mother when speaking to outsiders.","ru":"Используется при обращении к маме или о чужой матери; о своей матери посторонним обычно говорят 母."}},"お父さん":{"b":"お父さん (おとうさん)","p":"n","m":{"az":"ata","en":"father; dad","ru":"папа; отец"},"n":{"az":"Ataya müraciətdə və başqasının atası haqqında işlənir; kənar şəxslərə öz atandan danışarkən adətən 父 deyilir.","en":"Used to address your father or refer to someone else's; use 父 for your own father when speaking to outsiders.","ru":"Используется при обращении к папе или о чужом отце; о своём отце посторонним обычно говорят 父."}},"お菓子":{"b":"お菓子 (おかし)","p":"n","m":{"az":"şirniyyat; qəlyanaltı","en":"sweets; snacks","ru":"сладости; снеки"}},"お誕生":{"b":"誕生 (たんじょう)","p":"n","m":{"az":"doğulma, dünyaya gəlmə","en":"birth","ru":"рождение"},"n":{"az":"お nəzakət bildirir; “ad günü” isə お誕生日 sözüdür.","en":"お adds politeness; “birthday” is お誕生日.","ru":"お придаёт вежливость; «день рождения» обозначается словом お誕生日."}},"か":{"b":"か","p":"pt","m":{"az":"sual hissəciyi","en":"question particle","ru":"вопросительная частица"},"n":{"az":"Cümlənin sonuna gəlir və onu suala çevirir: 学生ですか = Tələbəsən? Yaponcada sual işarəsi əvəzinə adətən 。 yazılır.","en":"Goes at the end and turns the sentence into a question: 学生ですか = Are you a student? Japanese usually writes 。 instead of ?.","ru":"Ставится в конце и делает предложение вопросом: 学生ですか = Вы студент? Обычно пишут 。, а не ?."}},"から":{"b":"から","p":"pt","m":{"az":"-dan, -dən (haradan)","en":"from","ru":"из, от"},"n":{"az":"Başlanğıc nöqtəsini göstərir: 月から来ました = Aydan gəldim.","en":"Marks the starting point: 月から来ました = I came from the Moon.","ru":"Указывает исходную точку: 月から来ました = Я прилетела с Луны."}},"が":{"b":"が","p":"pt","m":{"az":"subyekt hissəciyi","en":"subject marker","ru":"частица подлежащего"},"n":{"az":"Hərəkəti edən və ya mövcud olan şeyi göstərir: 先生が来ました = müəllim gəldi. Yeni məlumatı vurğulayır; は isə artıq bəlli mövzunu.","en":"Marks who does the action or what exists: 先生が来ました = a teacher came. Introduces new information, while は marks a known topic.","ru":"Отмечает деятеля или то, что существует: 先生が来ました = пришёл учитель. Вводит новую информацию; は – уже известную тему."}},"きれい":{"b":"きれい","p":"an","m":{"az":"gözəl, təmiz","en":"beautiful, clean","ru":"красивый, чистый"},"n":{"az":"な-sifətdir: きれいな花 = gözəl çiçək; い ilə bitsə də い-sifət deyil.","en":"A na-adjective despite ending in い: きれいな花 = beautiful flower.","ru":"Это な-прилагательное, несмотря на окончание い: きれいな花 = красивый цветок."}},"ここ":{"b":"ここ","p":"pr","m":{"az":"bura; burada","en":"here; this place","ru":"здесь; это место"},"n":{"az":"Danışana yaxın yeri bildirir.","en":"Refers to a place near the speaker.","ru":"Указывает на место рядом с говорящим."}},"こと":{"b":"こと","p":"n","m":{"az":"iş; hadisə; məsələ","en":"thing; matter; event","ru":"дело; событие; обстоятельство"},"n":{"az":"Felə qoşularaq hərəkəti isimləşdirir: 読むこと oxumaq hərəkəti.","en":"It nominalizes verbs: 読むこと means the act of reading.","ru":"Превращает глагол в существительное: 読むこと означает чтение."}},"この":{"b":"この","p":"dm","m":{"az":"bu","en":"this","ru":"этот"},"n":{"az":"この大学 = bu universitet.","en":"この大学 = this university.","ru":"この大学 = этот университет."}},"これ":{"b":"これ","p":"pr","m":{"az":"bu; bu şey","en":"this; this thing","ru":"это; эта вещь"},"n":{"az":"Danışana yaxın şeyi bildirir və isimdən əvvəl işlənmir; isimdən əvvəl この gəlir.","en":"Refers to something near the speaker; use この before a noun.","ru":"Указывает на предмет рядом с говорящим; перед существительным используется この."}},"ござる":{"b":"ござる","p":"v","m":{"az":"olmaq; mövcud olmaq (çox nəzakətli)","en":"to be; to exist (very polite)","ru":"быть; иметься (очень вежливо)"},"n":{"az":"ございます ifadəsi あります sözünün daha nəzakətli formasıdır.","en":"ございます is a more polite form of あります.","ru":"ございます - более вежливая форма あります."}},"すぐ":{"b":"すぐ","p":"ad","m":{"az":"tez, dərhal","en":"soon, immediately","ru":"сразу, скоро"},"n":{"az":"すぐに = dərhal.","en":"すぐに = right away.","ru":"すぐに = сразу."}},"すごい":{"b":"すごい","p":"ai","m":{"az":"möhtəşəm; heyrətamiz","en":"amazing; incredible","ru":"потрясающий; удивительный"},"n":{"az":"い-sifətdir və danışıqda heyrət ifadə edir.","en":"It is an i-adjective often used to express amazement.","ru":"Это i-прилагательное, часто выражающее восхищение."}},"する":{"b":"する","p":"v","m":{"az":"etmək; (səs, iy) gəlmək","en":"to do; (a sound) to be heard","ru":"делать; (о звуке) слышаться"},"n":{"az":"Ən çox işlənən feil. 音がしました = səs gəldi. 〜ようとしました = ...-mağa çalışdı.","en":"Most common verb. 音がしました = there was a sound. 〜ようとしました = tried to ...","ru":"Самый частый глагол. 音がしました = раздался звук. 〜ようとしました = попытался ..."}},"ずつ":{"b":"ずつ","p":"pt","m":{"az":"...-ar, hərəsi bir","en":"each, apiece","ru":"по (одному)"},"n":{"az":"一つずつ = hərəsi bir dənə.","en":"一つずつ = one each.","ru":"一つずつ = по одному."}},"そう":{"b":"そう","p":"ad","m":{"az":"elə; belə","en":"so; that way","ru":"так"},"n":{"az":"そうです təsdiq, そうします isə deyilən şəkildə hərəkət etməyi bildirir.","en":"そうです confirms something; そうします means to do it that way.","ru":"そうです выражает подтверждение, а そうします означает сделать именно так."}},"そこ":{"b":"そこ","p":"pr","m":{"az":"ora","en":"there","ru":"там"},"n":{"az":"Dinləyiciyə yaxın və ya söhbətdə artıq qeyd olunan yeri göstərir.","en":"Refers to a place near the listener or already mentioned.","ru":"Обозначает место рядом с собеседником или уже упомянутое место."}},"そして":{"b":"そして","p":"cj","m":{"az":"və, sonra","en":"and, then","ru":"и, затем"}},"そっと":{"b":"そっと","p":"ad","m":{"az":"ehmalca, yavaşca","en":"gently, softly","ru":"осторожно, тихонько"}},"その":{"b":"その","p":"dm","m":{"az":"o (bəhs edilən)","en":"that (the one mentioned)","ru":"тот, этот (упомянутый)"},"n":{"az":"その時 = o vaxt, elə bu an.","en":"その時 = at that moment.","ru":"その時 = в тот момент."}},"それから":{"b":"それから","p":"cj","m":{"az":"sonra, ondan sonra","en":"then, after that","ru":"потом, затем"}},"たくさん":{"b":"たくさん","p":"ad","m":{"az":"çox; çoxlu","en":"many; much; a lot","ru":"много"},"n":{"az":"İsimlə たくさんの本, fellə isə たくさん食べる şəklində işlənir.","en":"Use たくさんの本 with a noun and たくさん食べる with a verb.","ru":"С существительным употребляется たくさんの本, с глаголом たくさん食べる."}},"たぬき":{"b":"狸 (たぬき)","p":"n","m":{"az":"yenotabənzər it; tanuki","en":"raccoon dog; tanuki","ru":"енотовидная собака; тануки"},"n":{"az":"Yapon nağıllarında tez-tez başqa surətə girən heyvan kimi təsvir olunur.","en":"Often portrayed in Japanese folktales as an animal that changes shape.","ru":"В японских сказках часто изображается животным, способным менять облик."}},"つく":{"b":"つく (着く)","p":"v","m":{"az":"çatmaq, yetişmək","en":"to arrive, to reach","ru":"прибывать, добираться"},"n":{"az":"I qrup feldir: 駅に着く = stansiyaya çatmaq; つきませんでした = çatmadı.","en":"A Group 1 verb: 駅に着く = to arrive at the station; つきませんでした = did not arrive.","ru":"Глагол I группы: 駅に着く = прибыть на станцию; つきませんでした = не прибыл."}},"で":{"b":"で","p":"pt","m":{"az":"-da/-də (hərəkətin yeri); ilə (vasitə)","en":"at, in (place of action); with, by (means)","ru":"в, на (место действия); с помощью"},"n":{"az":"Hərəkətin baş verdiyi yer: 山で竹を切る = dağda bambuk kəsmək; 庭で泣く = bağçada ağlamaq. Vasitə: 両手で = iki əllə. Varlıq üçün に işlənir, hərəkət üçün で.","en":"Place where an action happens: 山で = on the mountain; means: 両手で = with both hands. Existence uses に, actions use で.","ru":"Место действия: 山で = в горах; средство: 両手で = обеими руками. Для существования – に, для действия – で."}},"です":{"b":"です","p":"cp","m":{"az":"-dır, -dir (nəzakətli)","en":"is, am, are (polite)","ru":"есть, является (вежл.)"},"n":{"az":"İsmin sonunda gəlir: 学生です = Tələbəyəm / tələbədir. İndiki zaman, təsdiq, nəzakətli forma. Şəxs bildirmir: kontekstdən anlaşılır.","en":"Ends a noun sentence: 学生です = I am / he is a student. Present, affirmative, polite. It shows no person: context tells.","ru":"Завершает именное предложение: 学生です = я студент / он студент. Настоящее время, утверждение, вежливо. Лицо не выражает."}},"でも":{"b":"でも","p":"cj","m":{"az":"amma, lakin","en":"but","ru":"но"},"n":{"az":"Cümlənin əvvəlində gəlir və əvvəlki fikrə zidd fikir gətirir.","en":"Starts a sentence and introduces a contrast.","ru":"Начинает предложение и вводит противопоставление."}},"と":{"b":"と","p":"pt","m":{"az":"ilə; (sitat) deyə","en":"and, with; (quote marker)","ru":"и, с; (цитата)"},"n":{"az":"İki mənası var: 1) おじいさんとおばあさん = baba və nənə; 2) sitatdan sonra: 「森です」と言いました = «Moriyəm» dedi. 〜と思う = ...deyə düşünmək. Feildən sonra (開けると) isə 'edəndə, ...-ınca' deməkdir.","en":"Two main uses: 1) 'and' between nouns; 2) after a quote: 「…」と言いました = said \"…\". After a verb (開けると) it means 'when/as soon as'.","ru":"Основные значения: 1) 'и' между существительными; 2) после цитаты: 「…」と言いました = сказал «…». После глагола (開けると) – 'когда/как только'."}},"とても":{"b":"とても","p":"ad","m":{"az":"çox","en":"very","ru":"очень"}},"どう":{"b":"どう","p":"ad","m":{"az":"necə, nə cür","en":"how, in what way","ru":"как, каким образом"},"n":{"az":"どうですか = necədir, nə fikirləşirsiniz?","en":"どうですか asks how something is or what someone thinks.","ru":"どうですか означает «как это?» или «что вы думаете?»."}},"なめる":{"b":"なめる","p":"v","m":{"az":"yalamaq","en":"to lick","ru":"лизать"},"n":{"az":"Yalanan əşya を ilə göstərilir: お皿をなめる.","en":"The object licked takes を: お皿をなめる.","ru":"Предмет, который лижут, обозначается через を: お皿をなめる."}},"なる":{"b":"なる","p":"v","m":{"az":"olmaq, çevrilmək","en":"to become","ru":"становиться"},"n":{"az":"N/na-sifət + に なる; i-sifət: い → く なる (大きくなる = böyümək).","en":"N/na-adj + に なる; i-adj: い → く なる (大きくなる = grow big).","ru":"N/na-прил. + に なる; i-прил.: い → く なる (大きくなる = вырасти)."}},"に":{"b":"に","p":"pt","m":{"az":"-a/-ə; -da/-də; -ı (hədəf)","en":"to; at, in; (target)","ru":"в, на; к (цель)"},"n":{"az":"Çoxmənalı hissəcik: yer (教室の前に立つ = sinifin qabağında dayanmaq), istiqamət/hədəf (大学に来る = universitetə gəlmək), zaman (二年前に = iki il əvvəl), nəticə (静かになる). Mənanı feil müəyyən edir.","en":"Many uses: location of existence/position, destination or target, a point in time, the result of a change. The verb decides which.","ru":"Многозначная частица: место (стоять перед), направление/цель (прийти в университет), время (два года назад), результат изменения. Значение задаёт глагол."}},"にこにこ":{"b":"にこにこ","p":"ad","m":{"az":"gülümsəyərək","en":"with a cheerful smile","ru":"с улыбкой"},"n":{"az":"にこにこする = gülümsəmək, adətən səssiz və şən şəkildə.","en":"にこにこする means to smile cheerfully, usually without laughing aloud.","ru":"にこにこする означает приветливо улыбаться, обычно без громкого смеха."}},"ね":{"b":"ね","p":"pt","m":{"az":"elə deyilmi?; hə?","en":"right?; isn't it?","ru":"правда?; ведь"},"n":{"az":"Cümlə sonunda təsdiq və ortaq hiss bildirir, məsələn 寒いですね, əmri yumşaldır, məsələn 来てね, danışıqda isə 私はね kimi diqqət çəkir.","en":"At sentence end it seeks agreement or shares a feeling, as in 寒いですね, softens requests, as in 来てね, and conversationally draws attention, as in 私はね.","ru":"В конце фразы выражает ожидание согласия или общее чувство, как в 寒いですね, смягчает просьбу, как в 来てね, и привлекает внимание, как в 私はね."}},"の":{"b":"の","p":"pt","m":{"az":"-ın, -in (yiyəlik); iki ismi bağlayır","en":"of, -'s; links two nouns","ru":"связывает два существительных (род. падеж)"},"n":{"az":"N1 の N2: N1 N2-ni təyin edir. さくら大学の学生 = Sakura Universitetinin tələbəsi; ロボットの先生 = robot müəllim (növ bildirir).","en":"N1 の N2: N1 describes N2. さくら大学の学生 = a student of Sakura University; ロボットの先生 = a robot teacher (kind).","ru":"N1 の N2: N1 определяет N2. さくら大学の学生 = студент университета Сакура; ロボットの先生 = учитель-робот (вид)."}},"は":{"b":"は (wa)","p":"pt","m":{"az":"mövzu hissəciyi","en":"topic marker","ru":"частица темы"},"n":{"az":"Cümlənin nədən bəhs etdiyini göstərir. Yazılışı は, amma hissəcik kimi 'wa' oxunur: わたしは = 'mənə gəlincə / mən'.","en":"Marks what the sentence is about. Written は but read 'wa' as a particle: わたしは = 'as for me'.","ru":"Отмечает, о чём предложение. Пишется は, но как частица читается 'wa': わたしは = 'что касается меня'."}},"びっくり":{"b":"びっくり","p":"ad","m":{"az":"təəccüb; diksinmə","en":"surprise; startlement","ru":"удивление; испуг"},"n":{"az":"びっくりする təəccüblənmək və ya qəfil diksinmək deməkdir.","en":"びっくりする means to be surprised or startled.","ru":"びっくりする означает удивиться или вздрогнуть от неожиданности."}},"ふしぎ":{"b":"不思議 (ふしぎ)","p":"an","m":{"az":"sirli, qəribə, möcüzəli","en":"mysterious, strange","ru":"странный, загадочный"},"n":{"az":"na-sifətdir: ふしぎな先生 = sirli müəllim.","en":"na-adjective: ふしぎな先生 = a mysterious teacher.","ru":"na-прилагательное: ふしぎな先生 = загадочный учитель."}},"へ":{"b":"へ (e)","p":"pt","m":{"az":"-a/-ə (istiqamət)","en":"to, toward","ru":"к, в (направление)"},"n":{"az":"İstiqamət bildirir: 家へ帰る = evə qayıtmaq. Hissəcik kimi 'e' oxunur.","en":"Shows direction: 家へ帰る = go home. Read 'e' as a particle.","ru":"Направление: 家へ帰る = вернуться домой. Как частица читается 'e'."}},"ぼく":{"b":"僕 (ぼく)","p":"pr","m":{"az":"mən","en":"I","ru":"я"},"n":{"az":"Əsasən oğlanların və kişilərin işlətdiyi birinci şəxs əvəzliyidir.","en":"A first-person pronoun used mainly by boys and men.","ru":"Местоимение первого лица, употребляемое преимущественно мальчиками и мужчинами."}},"また":{"b":"また","p":"ad","m":{"az":"yenə, təkrar","en":"again","ru":"снова"}},"まだ":{"b":"まだ","p":"ad","m":{"az":"hələ","en":"still, yet","ru":"ещё"}},"みんな":{"b":"みんな","p":"n","m":{"az":"hamı, hamısı","en":"everyone, all","ru":"все"}},"むかしむかし":{"b":"昔々 (むかしむかし)","p":"ex","m":{"az":"biri var idi, biri yox idi","en":"once upon a time","ru":"давным-давно"},"n":{"az":"Yapon nağıllarının ənənəvi başlanğıcı.","en":"The traditional opening of Japanese tales.","ru":"Традиционное начало японских сказок."}},"も":{"b":"も","p":"pt","m":{"az":"də, da (həmçinin)","en":"also, too","ru":"тоже, также"},"n":{"az":"は-nin yerinə gəlir: ケンさんも = 'Ken də'. は ilə birlikdə işlənmir.","en":"Replaces は: ケンさんも = 'Ken too'. Not used together with は.","ru":"Ставится вместо は: ケンさんも = 'Кен тоже'. Вместе с は не используется."}},"もう":{"b":"もう","p":"ad","m":{"az":"daha; artıq","en":"more; already","ru":"ещё; уже"},"n":{"az":"もう一度 = bir daha.","en":"もう一度 = once more.","ru":"もう一度 = ещё раз."}},"や":{"b":"や","p":"pt","m":{"az":"və, ... kimi","en":"and, things such as","ru":"и, например"},"n":{"az":"や tam olmayan siyahı yaradır: 犬や猫（など）; nida və çağırışda da işlənir: おや、太郎や.","en":"や gives a non-exhaustive list, 犬や猫（など）, and also appears in exclamations or calls, おや、太郎や.","ru":"や обозначает неполный перечень, 犬や猫（など）, а также встречается в восклицаниях и обращениях: おや、太郎や."}},"やっと":{"b":"やっと","p":"ad","m":{"az":"nəhayət, güclə","en":"finally, barely","ru":"наконец, едва"},"n":{"az":"Uzun gözləmə və ya çətinlikdən sonra nəticəni, bəzən də güclə çatmağı bildirir.","en":"Indicates a result after waiting or effort, or sometimes barely managing something.","ru":"Обозначает результат после ожидания или усилий, иногда достижение чего-либо с трудом."}},"よ":{"b":"よ","p":"pt","m":{"az":"cümləsonu vurğu ədatı","en":"sentence-final emphasis particle","ru":"конечная усилительная частица"},"n":{"az":"Cümlənin sonunda yeni məlumatı, əminliyi və ya xəbərdarlığı vurğulayır: ここですよ “Buradadır”, 危ないよ “Ehtiyatlı ol”; 行こうよ kimi ifadələrdə çağırışı gücləndirir.","en":"At sentence end, it stresses information, assurance, or warning, as in ここですよ “It's here” and 危ないよ “Watch out,” and strengthens invitations such as 行こうよ “Let's go.”","ru":"В конце предложения подчёркивает сообщение, уверенность или предупреждение: ここですよ «Это здесь», 危ないよ «Осторожно», а также усиливает призыв: 行こうよ «Пойдём»."}},"よく":{"b":"よく","p":"ad","m":{"az":"yaxşıca, diqqətlə","en":"well, carefully","ru":"хорошо, внимательно"}},"より":{"b":"より","p":"pt","m":{"az":"-dan/-dən daha (müqayisə)","en":"than","ru":"чем"},"n":{"az":"さっきより明るく = bayaqkından daha parlaq.","en":"さっきより明るく = brighter than before.","ru":"さっきより明るく = ярче, чем раньше."}},"わかる":{"b":"分かる (わかる)","p":"v","m":{"az":"başa düşmək; anlamaq","en":"understand","ru":"понимать"},"n":{"az":"Başa düşülən şey adətən が ilə göstərilir: 日本語が分かる.","en":"What is understood usually takes が: 日本語が分かる.","ru":"То, что понимают, обычно оформляется частицей が: 日本語が分かる."}},"を":{"b":"を (o)","p":"pt","m":{"az":"təsirlik hissəcik (-ı, -i)","en":"object marker","ru":"частица прямого объекта"},"n":{"az":"Feilin təsir etdiyi əşyanı göstərir: かばんを持つ = çantanı tutmaq. Yazılışı を, oxunuşu 'o'.","en":"Marks the direct object: かばんを持つ = hold a bag. Written を, read 'o'.","ru":"Отмечает прямое дополнение: かばんを持つ = держать сумку. Пишется を, читается 'o'."}},"ん":{"b":"ん (← の)","p":"pt","m":{"az":"(izah bildirir)","en":"(explanatory)","ru":"(пояснение)"},"n":{"az":"〜んです / 〜のです: səbəb və ya izah verəndə işlənir; danışıqda の → ん.","en":"〜んです / 〜のです adds an explanation; in speech の becomes ん.","ru":"〜んです / 〜のです – объяснение; в речи の → ん."}},"ケーキ":{"b":"ケーキ","p":"n","m":{"az":"tort, pirojna","en":"cake","ru":"торт, пирожное"}},"テーブル":{"b":"テーブル","p":"n","m":{"az":"masa","en":"table","ru":"стол"}},"ノート":{"b":"ノート","p":"n","m":{"az":"dəftər","en":"notebook","ru":"тетрадь"}},"ベッド":{"b":"ベッド","p":"n","m":{"az":"çarpayı","en":"bed","ru":"кровать"}},"ロボット":{"b":"ロボット","p":"n","m":{"az":"robot","en":"robot","ru":"робот"},"n":{"az":"Katakana ilə yazılır, çünki xarici mənşəli sözdür.","en":"Written in katakana because it is a loanword.","ru":"Пишется катаканой, так как это заимствование."}},"一つ":{"b":"一つ (ひとつ)","p":"n","m":{"az":"bir (dənə)","en":"one (thing)","ru":"одна (штука)"},"n":{"az":"Ümumi sayğac: 一つ, 二つ, 三つ.","en":"General counter: 一つ, 二つ, 三つ.","ru":"Общий счёт: 一つ, 二つ, 三つ."}},"一度":{"b":"一度 (いちど)","p":"n","m":{"az":"bir dəfə","en":"once","ru":"один раз"}},"一番":{"b":"一番 (いちばん)","p":"ad","m":{"az":"ən; hamıdan çox","en":"most; best","ru":"самый; больше всего"},"n":{"az":"Sifətdən əvvəl üstünlük bildirir: 一番大きい = ən böyük; isim kimi «birinci yer» deməkdir.","en":"Before an adjective it marks the superlative: 一番大きい = biggest; as a noun it means first place.","ru":"Перед прилагательным выражает превосходную степень: 一番大きい = самый большой; как существительное означает первое место."}},"一緒":{"b":"一緒 (いっしょ)","p":"n","m":{"az":"birlik, bir yerdə olma","en":"being together","ru":"совместность, пребывание вместе"},"n":{"az":"一緒に “birlikdə” deməkdir: 友達と一緒に “dostla birlikdə”.","en":"一緒に means “together,” as in 友達と一緒に “together with a friend.”","ru":"一緒に означает «вместе»: 友達と一緒に «вместе с другом»."}},"三つ":{"b":"三つ (みっつ)","p":"n","m":{"az":"üç (dənə)","en":"three (things)","ru":"три (штуки)"}},"三つ目":{"b":"三つ目 (みっつめ)","p":"nu","m":{"az":"üçüncü","en":"third","ru":"третий"},"n":{"az":"目 say sözünə əlavə edilərək sıra bildirir: 三つ目 üçüncü deməkdir.","en":"目 turns a counter expression into an ordinal: 三つ目 means third.","ru":"目 после счётного выражения обозначает порядок: 三つ目 значит «третий»."}},"上":{"b":"上 (うえ)","p":"n","m":{"az":"üst","en":"top, above","ru":"верх, на"},"n":{"az":"N の 上 = N-in üstü.","en":"N の 上 = on top of N.","ru":"N の 上 = на N."}},"上手":{"b":"上手 (じょうず)","p":"an","m":{"az":"bacarıqlı, yaxşı bacaran","en":"skillful, good at","ru":"умелый, хорошо умеющий"},"n":{"az":"な-sifətdir: ピアノが上手です = pianoda yaxşı çalır.","en":"A na-adjective: ピアノが上手です = is good at playing piano.","ru":"な-прилагательное: ピアノが上手です = хорошо играет на пианино."}},"下":{"b":"下 (した)","p":"n","m":{"az":"alt, aşağı","en":"below, under","ru":"низ, под"},"n":{"az":"その下に = onun altına.","en":"その下に = under it.","ru":"その下に = под этим."}},"中":{"b":"中 (なか)","p":"n","m":{"az":"iç","en":"inside","ru":"внутри"},"n":{"az":"N の 中 = N-in içi.","en":"N の 中 = inside N.","ru":"N の 中 = внутри N."}},"二人":{"b":"二人 (ふたり)","p":"n","m":{"az":"iki nəfər, ikisi","en":"two people","ru":"двое"},"n":{"az":"İnsan sayğacı: 一人 (ひとり), 二人 (ふたり), 三人 (さんにん).","en":"People counter: 一人, 二人, 三人.","ru":"Счёт людей: 一人, 二人, 三人."}},"人":{"b":"人 (ひと)","p":"n","m":{"az":"adam, insan","en":"person","ru":"человек"},"n":{"az":"Tək işlənəndə ひと oxunur. Ölkə adından sonra じん olur: 日本人 (にほんじん) = yapon.","en":"Read ひと on its own. After a country it becomes じん: 日本人 = Japanese person.","ru":"Отдельно читается ひと. После названия страны – じん: 日本人 = японец."}},"今":{"b":"今 (いま)","p":"n","m":{"az":"indi","en":"now","ru":"сейчас"},"n":{"az":"今も = indi də.","en":"今も = even now.","ru":"今も = и сейчас."}},"今日":{"b":"今日 (きょう)","p":"n","m":{"az":"bu gün","en":"today","ru":"сегодня"}},"住む":{"b":"住む (すむ)","p":"v","m":{"az":"yaşamaq, məskunlaşmaq","en":"to live, to reside","ru":"жить, проживать"},"n":{"az":"住んで て-formadır, 場所に住む müəyyən yerdə yaşamaq deməkdir.","en":"住んで is the te-form, and 場所に住む means to live in a place.","ru":"住んで - форма на て, 場所に住む означает жить в определённом месте."}},"作る":{"b":"作る (つくる)","p":"v","m":{"az":"düzəltmək, yaratmaq","en":"to make","ru":"делать, создавать"},"n":{"az":"作ったのでした = (məlum oldu ki) düzəltmişdilər – izah bildirir.","en":"作ったのでした = (it turned out) they had made him.","ru":"作ったのでした = (оказалось) создали его."}},"使う":{"b":"使う (つかう)","p":"v","m":{"az":"istifadə etmək; işlətmək","en":"to use","ru":"использовать; пользоваться"},"n":{"az":"N を使う şəklində işlənir: パソコンを使う.","en":"Takes を for the object: パソコンを使う means to use a computer.","ru":"Используется с を для объекта: パソコンを使う означает пользоваться компьютером."}},"元気":{"b":"元気 (げんき)","p":"an","m":{"az":"gümrah; sağlam","en":"energetic; well","ru":"бодрый; здоровый"},"n":{"az":"な-sifətidir: 元気な子; 元気です = özünü yaxşı hiss edir.","en":"A な-adjective: 元気な子; 元気です means being well.","ru":"な-прилагательное: 元気な子; 元気です означает хорошее самочувствие."}},"先生":{"b":"先生 (せんせい)","p":"n","m":{"az":"müəllim; həkim","en":"teacher; doctor","ru":"учитель; доктор"},"n":{"az":"Başqasına müraciət kimi işlənir (ミミ先生 = Mimi həkim). Özün haqqında 先生 demirsən, 教師 deyirsən.","en":"Used to address others (ミミ先生 = Doctor Mimi). Never about yourself – then you say 教師.","ru":"Используется как обращение (ミミ先生 = доктор Мими). О себе так не говорят – говорят 教師."}},"入る":{"b":"入る (はいる)","p":"v","m":{"az":"girmək","en":"to enter","ru":"входить"},"n":{"az":"入り、 = girib (feilin kökü ilə bağlama).","en":"入り、 = went in and ...","ru":"入り、 = вошла и ..."}},"冷蔵庫":{"b":"冷蔵庫 (れいぞうこ)","p":"n","m":{"az":"soyuducu","en":"refrigerator","ru":"холодильник"}},"出る":{"b":"出る (でる)","p":"v","m":{"az":"çıxmaq","en":"to go out","ru":"выходить"},"n":{"az":"庭に出る = bağçaya çıxmaq.","en":"庭に出る = go out into the garden.","ru":"庭に出る = выйти в сад."}},"前":{"b":"前 (まえ)","p":"n","m":{"az":"qabaq, ön; əvvəl","en":"front; before","ru":"перед; раньше"},"n":{"az":"N の 前 = N-in qabağı. 二年前 = iki il əvvəl.","en":"N の 前 = in front of N. 二年前 = two years ago.","ru":"N の 前 = перед N. 二年前 = два года назад."}},"助ける":{"b":"助ける (たすける)","p":"v","m":{"az":"kömək etmək; xilas etmək","en":"help; rescue","ru":"помогать; спасать"},"n":{"az":"Təsirli feldir və kömək edilən şəxs を ilə göstərilir; 助かる xilas olmaq deməkdir.","en":"A transitive verb with the person helped marked by を; 助かる means to be saved.","ru":"Переходный глагол: человек, которому помогают, оформляется を; 助かる означает спастись."}},"動かす":{"b":"動かす (うごかす)","p":"v","m":{"az":"hərəkət etdirmək; tərpətmək","en":"to move something","ru":"двигать; перемещать"},"n":{"az":"Təsirlidir: 机を動かす; təsirsiz qarşılığı 動く-dur.","en":"Transitive: 机を動かす; its intransitive partner is 動く.","ru":"Переходный: 机を動かす; непереходная пара: 動く."}},"午後":{"b":"午後 (ごご)","p":"n","m":{"az":"günün ikinci yarısı","en":"p.m.; afternoon","ru":"после полудня"},"n":{"az":"Saatla gecə vaxtını da bildirə bilər: 午後九時 = axşam saat doqquz.","en":"With clock times, it also covers evening: 午後九時 = 9 p.m.","ru":"Со временем обозначает и вечер: 午後九時 = девять часов вечера."}},"友達":{"b":"友達 (ともだち)","p":"n","m":{"az":"dost","en":"friend","ru":"друг"}},"取る":{"b":"取る (とる)","p":"v","m":{"az":"götürmək, almaq","en":"to take, to pick up","ru":"брать, поднимать"},"n":{"az":"Əşyanı götürmək üçün 取る, şəkil çəkmək üçün eyni oxunuşlu 撮る işlənir.","en":"Use 取る for taking an object and the identically pronounced 撮る for taking a photo.","ru":"Для взятия предмета используется 取る, а для фотографии используется 撮る с тем же чтением."}},"古い":{"b":"古い (ふるい)","p":"ai","m":{"az":"köhnə; qədim","en":"old","ru":"старый; древний"},"n":{"az":"İ-sifətdir; əşya və tikililər üçün işlənir, insanın yaşını bildirmir.","en":"An i-adjective used for things and buildings, not a person's age.","ru":"И-прилагательное для вещей и зданий, не для возраста человека."}},"台所":{"b":"台所 (だいどころ)","p":"n","m":{"az":"mətbəx","en":"kitchen","ru":"кухня"}},"名前":{"b":"名前 (なまえ)","p":"n","m":{"az":"ad","en":"name","ru":"имя"}},"咲く":{"b":"咲く (さく)","p":"v","m":{"az":"çiçək açmaq","en":"to bloom, to blossom","ru":"цвести, распускаться"},"n":{"az":"Çiçəklər üçün işlənir: 桜が咲きます.","en":"Used for flowers: 桜が咲きます means cherry blossoms bloom.","ru":"Используется о цветах: 桜が咲きます означает сакура цветёт."}},"喜ぶ":{"b":"喜ぶ (よろこぶ)","p":"v","m":{"az":"sevinmək, şadlanmaq","en":"to rejoice, to be pleased","ru":"радоваться, обрадоваться"},"n":{"az":"I qrup feldir: 喜びました = sevindi; プレゼントを喜ぶ = hədiyyəyə sevinmək.","en":"A Group 1 verb: 喜びました = was pleased; プレゼントを喜ぶ = to be delighted with a gift.","ru":"Глагол I группы: 喜びました = обрадовался; プレゼントを喜ぶ = радоваться подарку."}},"回る":{"b":"回る (まわる)","p":"v","m":{"az":"fırlanmaq, dövrə vurmaq","en":"to turn, to go around","ru":"вращаться, обходить"},"n":{"az":"回る özü fırlanmaq, 回す isə nəyisə fırlatmaq deməkdir.","en":"回る means to turn by itself; 回す means to turn something.","ru":"回る означает вращаться, а 回す означает вращать что-либо."}},"困る":{"b":"困る (こまる)","p":"v","m":{"az":"çətin vəziyyətdə qalmaq; çətinlik çəkmək","en":"be in trouble; be at a loss","ru":"оказаться в затруднении"},"n":{"az":"困っている hazırda çətin vəziyyətdə olmağı bildirir; səbəb に ilə göstərilə bilər.","en":"困っている describes being in difficulty; the cause can be marked by に.","ru":"困っている описывает состояние затруднения; причина может оформляться に."}},"土曜":{"b":"土曜 (どよう)","p":"n","m":{"az":"şənbə","en":"Saturday","ru":"суббота"},"n":{"az":"土曜日 sözünün qısa formasıdır.","en":"Short for 土曜日.","ru":"Сокращение от 土曜日."}},"場所":{"b":"場所 (ばしょ)","p":"n","m":{"az":"yer","en":"place","ru":"место"}},"変":{"b":"変 (へん)","p":"an","m":{"az":"qəribə","en":"strange; odd","ru":"странный"},"n":{"az":"な-sifətidir: 変な音 = qəribə səs.","en":"A な-adjective: 変な音 = a strange sound.","ru":"な-прилагательное: 変な音 = странный звук."}},"夕方":{"b":"夕方 (ゆうがた)","p":"n","m":{"az":"axşamüstü","en":"evening","ru":"вечер"}},"外":{"b":"外 (そと)","p":"n","m":{"az":"çöl, bayır","en":"outside","ru":"снаружи"},"n":{"az":"N の 外 = N-in çölü: 窓の外 = pəncərənin arxası (çöldə).","en":"N の 外 = outside N.","ru":"N の 外 = снаружи N."}},"夜":{"b":"夜 (よる)","p":"n","m":{"az":"gecə","en":"night","ru":"ночь"}},"大きい":{"b":"大きい (おおきい)","p":"ai","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"大きくなる = böyümək (い → く + なる).","en":"大きくなる = grow up.","ru":"大きくなる = вырасти."}},"大きな":{"b":"大きな (おおきな)","p":"dm","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"Yalnız isimdən əvvəl gəlir; 大きい ilə eyni mənadadır.","en":"Only before a noun; same as 大きい.","ru":"Только перед сущ.; то же, что 大きい."}},"大切":{"b":"大切 (たいせつ)","p":"an","m":{"az":"vacib, əziz","en":"important, precious","ru":"важный, дорогой"},"n":{"az":"Na-sifətidir: 大切な物 “əziz əşya”; 大切にする “qayğı ilə yanaşmaq, əziz tutmaq” deməkdir.","en":"A na-adjective: 大切な物 “a precious thing”; 大切にする means “cherish or take good care of.”","ru":"Прилагательное на な: 大切な物 «дорогая вещь»; 大切にする означает «беречь, дорожить»."}},"女の子":{"b":"女の子 (おんなのこ)","p":"n","m":{"az":"qız uşağı","en":"girl","ru":"девочка"}},"好き":{"b":"好き (すき)","p":"an","m":{"az":"sevimli; sevmək","en":"liked; to like","ru":"любимый; нравиться"},"n":{"az":"N が好きです = N-i sevirəm. Yaponcada 'sevmək' sifətlə deyilir.","en":"N が好きです = I like N. 'To like' is an adjective in Japanese.","ru":"N が好きです = мне нравится N. 'Нравиться' – прилагательное."}},"子":{"b":"子 (こ)","p":"n","m":{"az":"uşaq; övlad","en":"child","ru":"ребёнок"},"n":{"az":"わたしの子 = mənim övladım.","en":"わたしの子 = my child.","ru":"わたしの子 = мой ребёнок."}},"学校":{"b":"学校 (がっこう)","p":"n","m":{"az":"məktəb","en":"school","ru":"школа"}},"家":{"b":"家 (いえ)","p":"n","m":{"az":"ev","en":"house, home","ru":"дом"}},"家族":{"b":"家族 (かぞく)","p":"n","m":{"az":"ailə","en":"family","ru":"семья"}},"寒い":{"b":"寒い (さむい)","p":"ai","m":{"az":"soyuq","en":"cold, chilly","ru":"холодный, прохладный"},"n":{"az":"い-sifətdir; əsasən hava üçün işlənir, toxunanda soyuq əşyalar üçün 冷たい deyilir.","en":"An i-adjective mainly for cold weather; use 冷たい for cold objects.","ru":"Прилагательное на い, обычно о погоде; для холодных предметов используют 冷たい."}},"小さい":{"b":"小さい (ちいさい)","p":"ai","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"i-sifət; isimdən əvvəl olduğu kimi gəlir: 小さい子 = balaca uşaq.","en":"i-adjective; goes straight before a noun: 小さい子 = a little child.","ru":"i-прилагательное; ставится прямо перед существительным."}},"小さな":{"b":"小さな (ちいさな)","p":"dm","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"Yalnız isimdən əvvəl gəlir (小さな音). Mənaca 小さい ilə eynidir.","en":"Only used before a noun; same meaning as 小さい.","ru":"Только перед существительным; то же, что 小さい."}},"少し":{"b":"少し (すこし)","p":"ad","m":{"az":"bir az","en":"a little","ru":"немного"}},"履く":{"b":"履く (はく)","p":"v","m":{"az":"ayağa geyinmək","en":"to put on footwear or lower-body clothing","ru":"надевать обувь или одежду на нижнюю часть тела"},"n":{"az":"Ayaqqabı, corab, şalvar üçün işlənir; 履いていました keçmişdə geyinmiş vəziyyəti bildirir.","en":"Used for shoes, socks and trousers; 履いていました describes a past state of wearing them.","ru":"Используется для обуви, носков и брюк; 履いていました описывает состояние в прошлом."}},"山":{"b":"山 (やま)","p":"n","m":{"az":"dağ","en":"mountain","ru":"гора"}},"帰る":{"b":"帰る (かえる)","p":"v","m":{"az":"qayıtmaq (evə, öz yerinə)","en":"to return home","ru":"возвращаться"},"n":{"az":"家へ帰るとちゅうで = evə qayıdarkən yolda.","en":"家へ帰るとちゅうで = on the way home.","ru":"家へ帰るとちゅうで = по дороге домой."}},"帽子":{"b":"帽子 (ぼうし)","p":"n","m":{"az":"papaq; şlyapa","en":"hat; cap","ru":"шляпа; шапка"}},"幸せ":{"b":"幸せ (しあわせ)","p":"an","m":{"az":"xoşbəxtlik, xoşbəxt","en":"happiness, happy","ru":"счастье, счастливый"},"n":{"az":"な-sifətdir; 幸せな人 - xoşbəxt insan.","en":"A na-adjective; 幸せな人 means a happy person.","ru":"Это na-прилагательное; 幸せな人 - счастливый человек."}},"座る":{"b":"座る (すわる)","p":"v","m":{"az":"oturmaq","en":"sit down","ru":"садиться"},"n":{"az":"Oturulan yer に ilə göstərilir: 椅子に座る “stulda oturmaq”.","en":"The seat or sitting place takes に: 椅子に座る “sit on a chair.”","ru":"Место обозначается с に: 椅子に座る «сесть на стул»."}},"庭":{"b":"庭 (にわ)","p":"n","m":{"az":"bağça, həyət","en":"garden, yard","ru":"сад, двор"}},"張る":{"b":"張る (はる)","p":"v","m":{"az":"yapışdırmaq, gərmək","en":"to put up, to stretch, to paste","ru":"натягивать, наклеивать"},"n":{"az":"I qrup feldir: ポスターを張る = poster asmaq; 張りました = asdı və ya gərdi.","en":"A Group 1 verb: ポスターを張る = to put up a poster; 張りました = put up or stretched.","ru":"Глагол I группы: ポスターを張る = повесить плакат; 張りました = натянул или прикрепил."}},"心配":{"b":"心配 (しんぱい)","p":"n","m":{"az":"narahatlıq, qayğı","en":"worry, concern","ru":"беспокойство, тревога"},"n":{"az":"心配する “narahat olmaq” deməkdir; 心配な şəklində na-sifəti kimi də işlənir.","en":"心配する means “worry”; 心配な is also used as a na-adjective.","ru":"心配する означает «беспокоиться»; форма 心配な также употребляется как прилагательное на な."}},"思う":{"b":"思う (おもう)","p":"v","m":{"az":"düşünmək, fikirləşmək","en":"to think","ru":"думать"},"n":{"az":"〜と思いました = ...deyə düşündü.","en":"〜と思いました = thought that ...","ru":"〜と思いました = подумал, что ..."}},"悪い":{"b":"悪い (わるい)","p":"ai","m":{"az":"pis, yaramaz","en":"bad, wrong","ru":"плохой, неправильный"},"n":{"az":"い-sifətdir: 悪くない = pis deyil; 調子が悪い = halı pis olmaq.","en":"An i-adjective: 悪くない = not bad; 調子が悪い = to feel unwell.","ru":"Прилагательное на い: 悪くない = неплохой; 調子が悪い = плохо себя чувствовать."}},"戸":{"b":"戸 (と)","p":"n","m":{"az":"qapı","en":"door","ru":"дверь"}},"手":{"b":"手 (て)","p":"n","m":{"az":"əl","en":"hand","ru":"рука"}},"手伝う":{"b":"手伝う (てつだう)","p":"v","m":{"az":"kömək etmək","en":"to help; to assist","ru":"помогать"},"n":{"az":"手伝いましょう təklif bildirir: kömək edim.","en":"手伝いましょう offers help: shall I help?","ru":"手伝いましょう выражает предложение помощи: давайте помогу."}},"新しい":{"b":"新しい (あたらしい)","p":"ai","m":{"az":"yeni","en":"new","ru":"новый"}},"日":{"b":"日 (ひ)","p":"n","m":{"az":"gün; günəş","en":"day; sun","ru":"день; солнце"},"n":{"az":"Müstəqil söz kimi çox vaxt ひ oxunur; tarixlərdə və birləşmələrdə oxunuşu dəyişir.","en":"Usually read ひ as a standalone word; its reading changes in dates and compounds.","ru":"Как отдельное слово обычно читается ひ; в датах и сложных словах чтение меняется."}},"日曜":{"b":"日曜 (にちよう)","p":"n","m":{"az":"bazar günü","en":"Sunday","ru":"воскресенье"}},"明日":{"b":"明日 (あした)","p":"n","m":{"az":"sabah","en":"tomorrow","ru":"завтра"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 明日行きます.","en":"Usually takes no に as a time expression: 明日行きます.","ru":"При обозначении времени обычно употребляется без に: 明日行きます."}},"昨日":{"b":"昨日 (きのう)","p":"n","m":{"az":"dünən","en":"yesterday","ru":"вчера"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 昨日来ました.","en":"Usually takes no に as a time expression: 昨日来ました.","ru":"При обозначении времени обычно употребляется без に: 昨日来ました."}},"時間":{"b":"時間 (じかん)","p":"n","m":{"az":"vaxt, saat","en":"time, hour","ru":"время, час"},"n":{"az":"食べる時間 = yemək vaxtı (feil isimdən əvvəl).","en":"食べる時間 = the time to eat.","ru":"食べる時間 = время еды."}},"暖かい":{"b":"暖かい (あたたかい)","p":"ai","m":{"az":"isti, ilıq","en":"warm","ru":"тёплый"},"n":{"az":"İ-sifətidir; əsasən hava və mühitin istiliyini, 温かい isə əşya, yemək və münasibətin istiliyini bildirir.","en":"An i-adjective mainly describing warm weather or surroundings; 温かい is used for objects, food, and personal warmth.","ru":"Прилагательное на い, обычно о тёплой погоде или обстановке; 温かい употребляется о предметах, еде и душевном тепле."}},"暗い":{"b":"暗い (くらい)","p":"ai","m":{"az":"qaranlıq, tutqun","en":"dark, gloomy","ru":"тёмный, мрачный"},"n":{"az":"İ-sifətidir və həm zəif işığı, həm də tutqun əhvalı bildirə bilər.","en":"An i-adjective that can describe low light or a gloomy mood.","ru":"Прилагательное на い, описывающее слабое освещение или мрачное настроение."}},"書く":{"b":"書く (かく)","p":"v","m":{"az":"yazmaq","en":"to write","ru":"писать"},"n":{"az":"「森」と書く = «Mori» yazmaq. 書いてある = yazılıb (yazılı durur).","en":"「森」と書く = write \"Mori\". 書いてある = is written.","ru":"「森」と書く = написать «Мори». 書いてある = написано."}},"朝":{"b":"朝 (あさ)","p":"n","m":{"az":"səhər","en":"morning","ru":"утро"}},"本当":{"b":"本当 (ほんとう)","p":"n","m":{"az":"həqiqət, doğru","en":"truth, reality","ru":"правда, истина"},"n":{"az":"本当です doğru deməkdir, 本当に isə həqiqətən mənasını verir.","en":"本当です means it is true, while 本当に means really.","ru":"本当です означает это правда, а 本当に - действительно."}},"机":{"b":"机 (つくえ)","p":"n","m":{"az":"yazı masası","en":"desk","ru":"письменный стол"}},"村":{"b":"村 (むら)","p":"n","m":{"az":"kənd","en":"village","ru":"деревня"}},"来る":{"b":"来る (くる)","p":"v","m":{"az":"gəlmək","en":"to come","ru":"приходить"},"n":{"az":"Qeyri-müntəzəm feildir: 来ます (kimasu), 来た (kita), 来て (kite). 〜から来ました = ...-dan gəlmişəm. 迎えに来る = aparmağa gəlmək.","en":"Irregular verb: 来ます, 来た (kita), 来て (kite). 〜から来ました = I come from ...","ru":"Неправильный глагол: 来ます, 来た (kita), 来て (kite). 〜から来ました = я из ..."}},"楽しい":{"b":"楽しい (たのしい)","p":"ai","m":{"az":"əyləncəli; xoş","en":"fun; enjoyable","ru":"весёлый; приятный"},"n":{"az":"İ-sifətdir; 楽しく onun zərf formasıdır.","en":"An i-adjective; 楽しく is its adverbial form.","ru":"И-прилагательное; 楽しく является его наречной формой."}},"次":{"b":"次 (つぎ)","p":"n","m":{"az":"növbəti; sonrakı","en":"next; following","ru":"следующий"},"n":{"az":"İsimdən əvvəl 次の, ardıcıllıq bildirmək üçün 次に işlənir.","en":"Use 次の before a noun and 次に to mean next in a sequence.","ru":"Перед существительным используется 次の, а для следующего шага 次に."}},"欲しい":{"b":"欲しい (ほしい)","p":"ai","m":{"az":"istəmək, arzulamaq","en":"to want, to desire","ru":"хотеть, желать"},"n":{"az":"い-sifətdir; istənilən əşya adətən が ilə işlənir: 水が欲しい.","en":"An i-adjective; the desired thing usually takes が: 水が欲しい.","ru":"Это i-прилагательное; желаемый предмет обычно отмечается が: 水が欲しい."}},"毎日":{"b":"毎日 (まいにち)","p":"n","m":{"az":"hər gün","en":"every day","ru":"каждый день"}},"毎晩":{"b":"毎晩 (まいばん)","p":"n","m":{"az":"hər axşam; hər gecə","en":"every evening; every night","ru":"каждый вечер; каждую ночь"},"n":{"az":"Vaxt bildirəndə に işlənmir: 毎晩読みます.","en":"Takes no に as a time expression: 毎晩読みます.","ru":"При обозначении времени употребляется без に: 毎晩読みます."}},"泣く":{"b":"泣く (なく)","p":"v","m":{"az":"ağlamaq","en":"to cry","ru":"плакать"}},"甘い":{"b":"甘い (あまい)","p":"ai","m":{"az":"şirin, yumşaq","en":"sweet, lenient","ru":"сладкий, снисходительный"},"n":{"az":"い-sifətdir: 甘くない = şirin deyil; davranış haqqında yumşaqlıq da bildirir.","en":"An i-adjective: 甘くない = not sweet; it can also mean lenient.","ru":"Прилагательное на い: 甘くない = несладкий; также может означать снисходительный."}},"用事":{"b":"用事 (ようじ)","p":"n","m":{"az":"iş, görüləsi məsələ","en":"errand, something to do","ru":"дело, поручение"},"n":{"az":"用事があります = işim var; şəxsi məşğuliyyəti bildirmək üçün işlənir.","en":"用事があります = I have something to do or an errand.","ru":"用事があります = у меня есть дело или поручение."}},"男":{"b":"男 (おとこ)","p":"n","m":{"az":"kişi","en":"man, male","ru":"мужчина"},"n":{"az":"Nəzakətli gündəlik nitqdə kişi üçün çox vaxt 男の人 işlənir.","en":"男の人 is often used for a man in polite everyday speech.","ru":"В вежливой повседневной речи о мужчине часто говорят 男の人."}},"男の子":{"b":"男の子 (おとこのこ)","p":"n","m":{"az":"oğlan","en":"boy","ru":"мальчик"}},"町":{"b":"町 (まち)","p":"n","m":{"az":"şəhərcik; məhəllə","en":"town; neighborhood","ru":"городок; квартал"}},"白い":{"b":"白い (しろい)","p":"ai","m":{"az":"ağ","en":"white","ru":"белый"}},"着る":{"b":"着る (きる)","p":"v","m":{"az":"geyinmək (paltar)","en":"to wear, put on","ru":"надевать"},"n":{"az":"白い服を着たねこ = ağ paltar geyinmiş pişik (feil təyin kimi).","en":"白い服を着たねこ = a cat wearing white.","ru":"白い服を着たねこ = кошка в белом."}},"私":{"b":"私 (わたし)","p":"pr","m":{"az":"mən","en":"I; me","ru":"я; меня"},"n":{"az":"Nəzakətli, neytral birinci şəxs əvəzliyidir və kontekstdən aydın olduqda buraxılır.","en":"A polite, neutral first-person pronoun, often omitted when clear from context.","ru":"Вежливое нейтральное местоимение первого лица, часто опускаемое, если понятно из контекста."}},"空":{"b":"空 (そら)","p":"n","m":{"az":"göy, səma","en":"sky","ru":"небо"}},"窓":{"b":"窓 (まど)","p":"n","m":{"az":"pəncərə","en":"window","ru":"окно"}},"笑う":{"b":"笑う (わらう)","p":"v","m":{"az":"gülmək, gülümsəmək","en":"to laugh, to smile","ru":"смеяться, улыбаться"},"n":{"az":"笑うと = gülümsəyəndə (feil + と = 'edəndə').","en":"笑うと = when he smiled.","ru":"笑うと = когда он улыбался."}},"答える":{"b":"答える (こたえる)","p":"v","m":{"az":"cavab vermək","en":"to answer","ru":"отвечать"}},"箱":{"b":"箱 (はこ)","p":"n","m":{"az":"qutu","en":"box","ru":"коробка"}},"糸":{"b":"糸 (いと)","p":"n","m":{"az":"sap","en":"thread","ru":"нить"}},"約束":{"b":"約束 (やくそく)","p":"n","m":{"az":"söz; görüş razılaşması","en":"promise; appointment","ru":"обещание; договорённость о встрече"},"n":{"az":"約束する = söz vermək və ya görüş barədə razılaşmaq.","en":"約束する means to promise or arrange to meet.","ru":"約束する означает обещать или договариваться о встрече."}},"紙":{"b":"紙 (かみ)","p":"n","m":{"az":"kağız","en":"paper","ru":"бумага"}},"考える":{"b":"考える (かんがえる)","p":"v","m":{"az":"düşünmək, fikirləşmək, nəzərdən keçirmək","en":"to think, to consider","ru":"думать, обдумывать, рассматривать"},"n":{"az":"〜について考える - bir mövzu haqqında düşünmək.","en":"〜について考える means to think about a topic.","ru":"〜について考える означает думать о какой-либо теме."}},"聞く":{"b":"聞く (きく)","p":"v","m":{"az":"soruşmaq; eşitmək, qulaq asmaq","en":"to ask; to hear, listen","ru":"спрашивать; слушать"},"n":{"az":"Burada 'soruşmaq': 「…」と聞くと = «…» deyə soruşanda.","en":"Here 'ask': 「…」と聞くと = when she asked \"…\".","ru":"Здесь 'спросить': 「…」と聞くと = когда спросила «…»."}},"聞こえる":{"b":"聞こえる (きこえる)","p":"v","m":{"az":"eşidilmək","en":"to be audible; to hear","ru":"быть слышным; слышаться"},"n":{"az":"Səs が ilə göstərilir: 歌が聞こえる; bu, qəsdən qulaq asmaq deyil, səsin qulağa çatmasıdır.","en":"The sound takes が: 歌が聞こえる; it describes audibility rather than deliberate listening.","ru":"Звук обозначается через が: 歌が聞こえる; речь о слышимости, а не о намеренном слушании."}},"胸":{"b":"胸 (むね)","p":"n","m":{"az":"sinə, köks","en":"chest, breast","ru":"грудь, грудная клетка"},"n":{"az":"胸がどきどきする = ürəyi həyəcanla döyünmək.","en":"胸がどきどきする = one's heart pounds with excitement or nervousness.","ru":"胸がどきどきする = сердце сильно бьётся от волнения."}},"花":{"b":"花 (はな)","p":"n","m":{"az":"çiçək","en":"flower","ru":"цветок"}},"若い":{"b":"若い (わかい)","p":"ai","m":{"az":"gənc, cavan","en":"young","ru":"молодой"},"n":{"az":"İ-sifətidir: 若い人 “gənc insan”.","en":"An i-adjective: 若い人 means “a young person.”","ru":"Прилагательное на い: 若い人 «молодой человек»."}},"茶色い":{"b":"茶色い (ちゃいろい)","p":"ai","m":{"az":"qəhvəyi","en":"brown","ru":"коричневый"},"n":{"az":"い sifətidir, 茶色い靴 - qəhvəyi ayaqqabı.","en":"An i-adjective, as in 茶色い靴, brown shoes.","ru":"Прилагательное на い, например 茶色い靴 - коричневые туфли."}},"行く":{"b":"行く (いく)","p":"v","m":{"az":"getmək","en":"go","ru":"идти; ехать"},"n":{"az":"İstiqamət に və ya へ ilə göstərilir; て forması 行って, keçmiş forması 行った olur.","en":"The destination takes に or へ; its irregular forms are 行って and 行った.","ru":"Направление обозначается に или へ; особые формы: 行って и 行った."}},"見せる":{"b":"見せる (みせる)","p":"v","m":{"az":"göstərmək","en":"show","ru":"показывать"},"n":{"az":"人に物を見せる kiməsə nəyisə göstərmək quruluşudur.","en":"Use 人に物を見せる to show something to someone.","ru":"Конструкция 人に物を見せる означает показать что-либо кому-либо."}},"見つける":{"b":"見つける (みつける)","p":"v","m":{"az":"tapmaq; aşkar etmək","en":"find; discover","ru":"находить; обнаруживать"},"n":{"az":"Təsirli feldir; 見つかる tapılmaq deməkdir.","en":"A transitive verb; 見つかる means to be found.","ru":"Переходный глагол; 見つかる означает найтись."}},"見る":{"b":"見る (みる)","p":"v","m":{"az":"baxmaq, görmək","en":"to see, to look","ru":"смотреть, видеть"},"n":{"az":"月を見てください = Aya baxın.","en":"月を見てください = please look at the moon.","ru":"月を見てください = смотрите на луну."}},"親切":{"b":"親切 (しんせつ)","p":"an","m":{"az":"mehriban, xeyirxah","en":"kind, helpful","ru":"добрый, отзывчивый"},"n":{"az":"な-sifətdir: 親切な人 = mehriban insan.","en":"A na-adjective: 親切な人 = kind person.","ru":"な-прилагательное: 親切な人 = добрый человек."}},"言う":{"b":"言う (いう)","p":"v","m":{"az":"demək","en":"to say","ru":"сказать, говорить"},"n":{"az":"「…」と言いました = «…» dedi. Oxunuşu 'iu' kimi səslənir.","en":"「…」と言いました = said \"…\". Pronounced 'yuu'.","ru":"「…」と言いました = сказал «…»."}},"赤い":{"b":"赤い (あかい)","p":"ai","m":{"az":"qırmızı","en":"red","ru":"красный"},"n":{"az":"赤く光る = qırmızı parlamaq (い → く: zərf).","en":"赤く光る = shine red (い → く: adverb).","ru":"赤く光る = светиться красным (い → く: наречие)."}},"起きる":{"b":"起きる (おきる)","p":"v","m":{"az":"oyanmaq; yataqdan qalxmaq","en":"to wake up; to get up","ru":"просыпаться; вставать"},"n":{"az":"Təsirsizdir; 起こす kimisə oyatmaq deməkdir.","en":"Intransitive; 起こす means to wake someone up.","ru":"Непереходный; 起こす означает будить кого-то."}},"足":{"b":"足 (あし)","p":"n","m":{"az":"ayaq","en":"foot; leg","ru":"нога; ступня"},"n":{"az":"Kontekstdən asılı olaraq ayağın pəncəsini və ya bütün aşağı ətrafı bildirir.","en":"Can mean the foot or the whole leg, depending on context.","ru":"В зависимости от контекста обозначает ступню или всю ногу."}},"近い":{"b":"近い (ちかい)","p":"ai","m":{"az":"yaxın","en":"near, close","ru":"близкий"},"n":{"az":"い-sifətdir; 〜に近い - bir yerə və ya şeyə yaxın.","en":"An i-adjective; 〜に近い means close to something.","ru":"Это i-прилагательное; 〜に近い означает близко к чему-либо."}},"近く":{"b":"近く (ちかく)","p":"n","m":{"az":"yaxınlıq, yaxın yer","en":"vicinity, nearby place","ru":"окрестности, близкое место"},"n":{"az":"Nの近く “N-in yaxınlığı”, 近くに isə “yaxınlıqda” deməkdir.","en":"Nの近く means “near N,” and 近くに means “nearby.”","ru":"Nの近く означает «рядом с N», а 近くに означает «поблизости»."}},"遊ぶ":{"b":"遊ぶ (あそぶ)","p":"v","m":{"az":"oynamaq; əylənmək","en":"to play; to have fun","ru":"играть; развлекаться"},"n":{"az":"て-forması 遊んで-dir; 友達と遊ぶ = dostlarla oynamaq və ya vaxt keçirmək.","en":"Its て-form is 遊んで; 友達と遊ぶ means to play or spend time with friends.","ru":"て-форма: 遊んで; 友達と遊ぶ означает играть или проводить время с друзьями."}},"部屋":{"b":"部屋 (へや)","p":"n","m":{"az":"otaq","en":"room","ru":"комната"}},"長い":{"b":"長い (ながい)","p":"ai","m":{"az":"uzun","en":"long","ru":"длинный; долгий"},"n":{"az":"İ-sifətdir və həm uzunluğu, həm də müddəti təsvir edir.","en":"An i-adjective describing both length and duration.","ru":"И-прилагательное, описывающее длину и длительность."}},"閉める":{"b":"閉める (しめる)","p":"v","m":{"az":"bağlamaq (qapı, pəncərə)","en":"to close; to shut","ru":"закрывать"},"n":{"az":"他動詞: 閉める bağlamaq, 閉まる isə bağlanmaq deməkdir.","en":"Transitive verb: 閉める means to close something, while 閉まる means to close by itself.","ru":"Переходный глагол: 閉める - закрывать, 閉まる - закрываться."}},"開く":{"b":"開く (あく)","p":"v","m":{"az":"açılmaq","en":"open","ru":"открываться"},"n":{"az":"Qapı üçün あく oxunur və təsirsizdir, təsirli qarşılığı 開ける olur; 開く həmçinin ひらく oxuna bilər.","en":"For doors, it is read あく and is intransitive, paired with 開ける; 開く can also be read ひらく.","ru":"О дверях читается あく и является непереходным, с парой 開ける; 開く также может читаться ひらく."}},"開ける":{"b":"開ける (あける)","p":"v","m":{"az":"açmaq","en":"to open","ru":"открывать"},"n":{"az":"開けると = açanda.","en":"開けると = when he opened.","ru":"開けると = когда открыл."}},"間":{"b":"間 (あいだ)","p":"n","m":{"az":"ara, aralıq, müddət","en":"between, interval, duration","ru":"между, промежуток, время"},"n":{"az":"AとBの間 iki şeyin arasını, 〜の間 isə müddəti bildirir.","en":"AとBの間 means between A and B, while 〜の間 can indicate duration.","ru":"AとBの間 означает между A и B, а 〜の間 может обозначать промежуток времени."}},"降る":{"b":"降る (ふる)","p":"v","m":{"az":"yağmaq","en":"fall as rain or snow","ru":"идти о дожде или снеге"},"n":{"az":"Yağıntı が ilə göstərilir: 雨が降る, 雪が降る.","en":"Precipitation takes が: 雨が降る, 雪が降る.","ru":"Осадки оформляются が: 雨が降る, 雪が降る."}},"雨":{"b":"雨 (あめ)","p":"n","m":{"az":"yağış","en":"rain","ru":"дождь"}},"雲":{"b":"雲 (くも)","p":"n","m":{"az":"bulud","en":"cloud","ru":"облако"}},"青い":{"b":"青い (あおい)","p":"ai","m":{"az":"mavi, göy","en":"blue","ru":"синий, голубой"}},"静か":{"b":"静か (しずか)","p":"an","m":{"az":"sakit, səssiz","en":"quiet","ru":"тихий"},"n":{"az":"静かになる = sakitləşmək (na-sifət + に + なる).","en":"静かになる = become quiet.","ru":"静かになる = стать тихим."}},"靴":{"b":"靴 (くつ)","p":"n","m":{"az":"ayaqqabı","en":"shoes","ru":"обувь, туфли"}},"音":{"b":"音 (おと)","p":"n","m":{"az":"səs (əşya səsi)","en":"sound","ru":"звук"},"n":{"az":"音がする = səs gəlmək. İnsan səsi üçün 声.","en":"音がする = a sound is heard. Human voice: 声.","ru":"音がする = слышен звук. Голос человека – 声."}},"頭":{"b":"頭 (あたま)","p":"n","m":{"az":"baş","en":"head","ru":"голова"}},"頼む":{"b":"頼む (たのむ)","p":"v","m":{"az":"xahiş etmək; sifariş vermək","en":"to request; to order","ru":"просить; заказывать"},"n":{"az":"頼みました keçmiş nəzakətli formadır.","en":"頼みました is the polite past form.","ru":"頼みました - вежливая форма прошедшего времени."}},"顔":{"b":"顔 (かお)","p":"n","m":{"az":"üz, sifət","en":"face","ru":"лицо"}},"飛ぶ":{"b":"飛ぶ (とぶ)","p":"v","m":{"az":"uçmaq, havada hərəkət etmək","en":"to fly","ru":"летать, лететь"},"n":{"az":"Təsirsiz feldir, 飛びました nəzakətli keçmiş formadır.","en":"An intransitive verb, with 飛びました as its polite past form.","ru":"Непереходный глагол, 飛びました - его вежливая прошедшая форма."}},"駅":{"b":"駅 (えき)","p":"n","m":{"az":"stansiya","en":"station","ru":"станция"}},"驚く":{"b":"驚く (おどろく)","p":"v","m":{"az":"təəccüblənmək; diksinmək","en":"to be surprised; to be startled","ru":"удивляться; пугаться"},"n":{"az":"Səbəb に ilə göstərilə bilər: 音に驚く = səsdən diksinmək.","en":"The cause can take に: 音に驚く = be startled by a sound.","ru":"Причина может обозначаться через に: 音に驚く = вздрогнуть от звука."}},"魔法":{"b":"魔法 (まほう)","p":"n","m":{"az":"sehr, sehrbazlıq","en":"magic, sorcery","ru":"магия, волшебство"},"n":{"az":"魔法を使う = sehr işlətmək.","en":"魔法を使う = to use magic or cast a spell.","ru":"魔法を使う = использовать магию или колдовать."}}}};